"use client";

import { FormEvent, Fragment, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Banknote, BarChart3, Bell, CalendarDays, ChevronDown, ChevronLeft, ChevronRight, Download, Eye, FileText, LayoutDashboard, LogOut, Menu, MessageCircle, PackageOpen, Pencil, Plus, Printer, ReceiptText, Search, ShieldCheck, Sparkles, Stethoscope, Trash2, TrendingDown, TrendingUp, Upload, UserPlus, Users, WalletCards, X } from "lucide-react";
import { toast } from "sonner";
import { Toaster } from "@/components/ui/sonner";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { DEFAULT_CONFIRMATION_MESSAGE, formatConfirmationMessage } from "@/lib/whatsapp-message";
import { BrandLogo } from "@/components/brand-logo";

type Patient = { id: number; name: string; phone: string; email: string; profilePhoto: string; notes: string; active: boolean; createdAt: string };
type ClinicPackage = { id: number; patientId: number; name: string; totalSessions: number; totalAmountCents: number; paidAmountCents: number; paymentMethod: string; paymentStatus: string; purchasedAt: string; lastPaymentAt: string | null; paymentDueDate: string | null; status: string };
type Session = { id: number; patientId: number; packageId: number | null; sessionKind: "package" | "standalone"; standaloneAmountCents: number; standalonePaidCents: number; standalonePaymentMethod: string; standaloneDueDate: string | null; performedAt: string; procedureType: string; measurementIn: string; measurementOut: string; occurrences: string; notes: string; sessionValueCents: number; coveredAmountCents: number; outstandingAmountCents: number; paymentStatus: "Paga" | "Pendente" | "Vencida" | "Sem cobrança"; isPartialPayment: boolean; paymentDueDate: string | null };
type Payment = { id: number; patientId: number; packageId: number; amountCents: number; method: string; paidAt: string; notes: string };
type Appointment = { id: number; patientId: number | null; title: string; scheduledAt: string; durationMinutes: number; isBackup: boolean; status: string; notes: string };
type WaitingListEntry = { id: number; patientId: number; preference: string; notes: string; createdAt: string };
type Expense = { id: number; description: string; category: string; amountCents: number; paidAt: string; notes: string };
type PatientDocument = { id: number; patientId: number; name: string; category: string; mimeType: string; sizeBytes: number; checksumSha256: string; createdAt: string };
type ClinicSettings = { confirmationMessage: string };
type ClinicData = { patients: Patient[]; packages: ClinicPackage[]; sessions: Session[]; payments: Payment[]; appointments: Appointment[]; waitingList: WaitingListEntry[]; expenses: Expense[]; documents: PatientDocument[]; settings: ClinicSettings };
type View = "overview" | "patients" | "record" | "packages" | "sessions" | "payments" | "agenda";
type RecordTab = "summary" | "sessions" | "packages" | "payments" | "documents" | "notes";
type Modal = "patient" | "patientEdit" | "package" | "packageEdit" | "session" | "sessionEdit" | "payment" | "appointment" | "appointmentEdit" | "block" | "expense" | "whatsappMessage" | null;
type DeleteTarget = { action: string; id: number; label: string } | null;

const inputDate = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const today = inputDate(new Date());
const dueDateDefault = (() => { const value = new Date(); value.setDate(value.getDate() + 30); return inputDate(value); })();
const emptyData: ClinicData = { patients: [], packages: [], sessions: [], payments: [], appointments: [], waitingList: [], expenses: [], documents: [], settings: { confirmationMessage: DEFAULT_CONFIRMATION_MESSAGE } };
const nav = [["overview", "Visão geral", LayoutDashboard], ["patients", "Pacientes", Users], ["packages", "Pacotes", PackageOpen], ["sessions", "Sessões", FileText], ["payments", "Financeiro", WalletCards], ["agenda", "Agenda", CalendarDays]] as const;
const mobileNav = [["overview", "Início", LayoutDashboard], ["patients", "Pacientes", Users], ["sessions", "Sessões", FileText], ["agenda", "Agenda", CalendarDays], ["payments", "Financeiro", WalletCards]] as const;
const money = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value / 100);
const dateBR = (value?: string | null) => value ? new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC" }).format(new Date(`${value.slice(0, 10)}T12:00:00Z`)) : "—";
const initials = (name: string) => name.split(" ").slice(0, 2).map((part) => part[0]).join("");
const whatsappNumber = (phone: string) => { let digits = phone.replace(/\D/g, ""); if (digits.startsWith("0") && (digits.length === 11 || digits.length === 12)) digits = digits.slice(1); return digits.startsWith("55") ? digits : digits.length === 10 || digits.length === 11 ? `55${digits}` : digits; };
const sessionCycle = (allSessions: Session[], session: Session) => { const ordered = [...allSessions].sort((a, b) => a.performedAt.localeCompare(b.performedAt) || a.id - b.id); const position = Math.max(0, ordered.findIndex((item) => item.id === session.id)); return { number: position % 5 + 1, cycle: Math.floor(position / 5) + 1 }; };
const packagePaymentState = (pkg: ClinicPackage) => pkg.totalAmountCents === 0 ? "Sem cobrança" : pkg.paidAmountCents >= pkg.totalAmountCents ? "Pago" : pkg.paymentDueDate && pkg.paymentDueDate.slice(0, 10) < today ? "Vencido" : "Pendente";
const paymentSettled = (value: string) => value === "Pago" || value === "Paga" || value === "Sem cobrança";

export default function ClinicDashboard() {
  const router = useRouter();
  const [data, setData] = useState(emptyData); const [view, setView] = useState<View>("overview"); const [modal, setModal] = useState<Modal>(null);
  const [query, setQuery] = useState(""); const [selectedId, setSelectedId] = useState(1); const [recordTab, setRecordTab] = useState<RecordTab>("summary"); const [menu, setMenu] = useState(false); const [saving, setSaving] = useState(false); const [connected, setConnected] = useState(false); const [deleteTarget, setDeleteTarget] = useState<DeleteTarget>(null); const [editingPatient, setEditingPatient] = useState<Patient | null>(null); const [editingSession, setEditingSession] = useState<Session | null>(null); const [editingPackage, setEditingPackage] = useState<ClinicPackage | null>(null); const [editingAppointment, setEditingAppointment] = useState<Appointment | null>(null); const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null); const [preferredAppointmentAt, setPreferredAppointmentAt] = useState(""); const [preferredAppointmentPatientId, setPreferredAppointmentPatientId] = useState<number | undefined>(); const [waitlistOpen, setWaitlistOpen] = useState(false);
  async function reloadClinic() { const response = await fetch("/api/clinic", { cache: "no-store" }); if (!response.ok) throw new Error("Não foi possível atualizar os dados."); const result = await response.json() as ClinicData; setData(result); setConnected(true); }
  useEffect(() => { fetch("/api/clinic", { cache: "no-store" }).then(async (response) => { if (!response.ok) throw new Error(); const result = await response.json() as ClinicData; setData(result); setConnected(true); }).catch(() => { setConnected(false); toast.error("Não foi possível carregar os dados reais. Tente novamente em instantes."); }); }, []);
  const name = (id: number | null) => id === null ? "Horário bloqueado" : data.patients.find((p) => p.id === id)?.name || "Paciente";
  const used = (id: number) => data.sessions.filter((s) => s.packageId === id).length;
  const remaining = (pkg: ClinicPackage) => Math.max(0, pkg.totalSessions - used(pkg.id));
  const filtered = data.patients.filter((p) => `${p.name} ${p.phone} ${p.email}`.toLowerCase().includes(query.toLowerCase()));
  const selected = data.patients.find((p) => p.id === selectedId) || data.patients[0];
  const selectedPackage = data.packages.find((p) => p.patientId === selected?.id && p.status !== "Concluído") || data.packages.find((p) => p.patientId === selected?.id);
  const pending = data.packages.filter((p) => !paymentSettled(packagePaymentState(p))).length + data.sessions.filter((session) => session.packageId === null && !paymentSettled(session.paymentStatus)).length;
  async function submit(event: FormEvent<HTMLFormElement>, action: string) { event.preventDefault(); setSaving(true); try { const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const response = await fetch("/api/clinic", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...values }) }); const result = await response.json() as ClinicData & { error?: string }; if (!response.ok) throw new Error(result.error); setData(result); setConnected(true); setModal(null); toast.success("Registro salvo com sucesso."); } catch (e) { toast.error(e instanceof Error ? e.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  async function mutate(action: string, payload: Record<string, unknown>, message: string) { setSaving(true); try { const response = await fetch("/api/clinic", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...payload }) }); const result = await response.json() as ClinicData & { error?: string }; if (!response.ok) throw new Error(result.error); setData(result); setConnected(true); setDeleteTarget(null); toast.success(message); return true; } catch (e) { toast.error(e instanceof Error ? e.message : "Não foi possível concluir."); return false; } finally { setSaving(false); } }
  const edit = (patient: Patient) => { setEditingPatient(patient); setModal("patientEdit"); };
  const editSession = (session: Session) => { setEditingSession(session); setModal("sessionEdit"); };
  const editPackage = (pkg: ClinicPackage) => { setEditingPackage(pkg); setModal("packageEdit"); };
  const openAppointment = (scheduledAt = "", patientId?: number) => { setPreferredAppointmentAt(scheduledAt); setPreferredAppointmentPatientId(patientId); setModal("appointment"); };
  const openBlock = (scheduledAt = "") => { setPreferredAppointmentAt(scheduledAt); setModal("block"); };
  const editAppointment = (appointment: Appointment) => { setSelectedAppointment(null); setEditingAppointment(appointment); setModal("appointmentEdit"); };
  const logout = async () => { await fetch("/api/auth/logout", { method: "POST" }); router.replace("/login"); router.refresh(); };
  const go = (next: View) => { setView(next); setMenu(false); };
  const openRecord = (id: number) => { setSelectedId(id); setRecordTab("summary"); setView("record"); setQuery(""); };
  return <div className="clinic-app min-h-screen bg-[#f6f8f6] text-[#17231f]"><Toaster position="top-right" richColors />
    <aside className={`clinic-sidebar fixed inset-y-0 left-0 z-40 w-[248px] bg-[#07533f] text-white transition-transform lg:translate-x-0 ${menu ? "translate-x-0" : "-translate-x-full"}`}><div className="flex h-full flex-col"><div className="flex items-center justify-between px-5 pb-8 pt-7"><button onClick={() => go("overview")} className="flex min-w-0 items-center gap-3 text-left"><BrandLogo size={56} className="rounded-2xl border-2 border-white shadow-md" /><span className="min-w-0"><strong className="block font-serif text-lg leading-5">Dra. Maria Carolini</strong><small className="text-white/60">Fisioterapeuta</small></span></button><button className="lg:hidden" onClick={() => setMenu(false)}><X /></button></div><nav className="space-y-1 px-3">{nav.map(([key, label, Icon]) => <button key={key} onClick={() => go(key)} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left text-[15px] ${view === key ? "bg-white/15" : "text-white/70 hover:bg-white/10 hover:text-white"}`}><Icon className="size-5" />{label}</button>)}</nav><div className="mt-auto p-5"><div className="sync-card rounded-2xl border border-white/10 bg-white/10 p-4 text-sm"><div className="flex items-center gap-2 font-medium"><span className={`sync-dot size-2 rounded-full ${connected ? "bg-emerald-300" : "bg-amber-300"}`} />{connected ? "Dados sincronizados" : "Conexão indisponível"}</div><p className="mt-2 text-xs leading-relaxed text-white/55">{connected ? "Pacientes, pacotes e pagamentos protegidos em um só lugar." : "Os dados reais não foram carregados. Atualize a página para tentar novamente."}</p></div></div></div></aside>
    {menu && <button aria-label="Fechar menu" className="fixed inset-0 z-[35] bg-[#071d16]/45 backdrop-blur-sm lg:hidden" onClick={() => setMenu(false)} />}
    <main className="clinic-main min-h-screen lg:pl-[248px]"><header className="clinic-topbar sticky top-0 z-30 flex h-[74px] items-center gap-4 border-b border-[#dfe6e1] bg-white/90 px-4 backdrop-blur-xl sm:px-7"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setMenu(true)}><Menu /></Button><div className="relative max-w-xl flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#718078]" /><Input value={query} onChange={(e) => { setQuery(e.target.value); setView("patients"); }} placeholder="Buscar pacientes, telefone ou e-mail..." className="h-11 rounded-xl bg-[#f6f8f6] pl-10" /></div><Button variant="ghost" size="icon" className="notification-button relative rounded-full" onClick={() => setWaitlistOpen(true)} title="Abrir lista de espera"><Bell className="size-5" />{data.waitingList.length > 0 && <span className="absolute -right-1 -top-1 grid min-w-5 place-items-center rounded-full bg-[#d69a42] px-1 text-[10px] font-bold text-white">{data.waitingList.length}</span>}</Button><div className="hidden items-center gap-3 border-l pl-5 sm:flex"><Avatar name="Maria Carolini" /><div><p className="text-sm font-semibold">Dra. Maria Carolini</p><p className="text-xs text-[#758078]">Fisioterapeuta</p></div></div><Button variant="ghost" size="icon" onClick={logout} title="Sair do sistema"><LogOut className="size-5" /></Button></header>
      <div className="clinic-content mx-auto max-w-[1500px] p-4 sm:p-7 lg:p-9"><div className="page-heading mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-1 text-sm font-medium text-[#608174]">Dra. Maria Carolini · Fisioterapeuta</p><h1 className="font-serif text-3xl font-semibold sm:text-4xl">{view === "record" ? "Prontuário do paciente" : nav.find(([key]) => key === view)?.[1]}</h1><p className="mt-1 text-sm text-[#758078]">{view === "record" ? "Sessões, pacotes, pagamentos e evolução em um só lugar." : "Informações atualizadas para uma rotina mais tranquila."}</p></div><div className="flex flex-wrap gap-2">{view === "overview" && <Button variant="outline" asChild><a href="/api/clinic?export=backup"><Download /> Fazer backup</a></Button>}{view === "agenda" && <Button variant="outline" onClick={() => openAppointment()}><CalendarDays /> Agendar</Button>}<Button variant="outline" onClick={() => setModal("package")}><PackageOpen /> Novo pacote</Button><Button className="bg-[#08684e] hover:bg-[#07533f]" onClick={() => setModal("patient")}><UserPlus /> Novo paciente</Button></div></div>
        {view === "overview" && <><section className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Users} label="Pacientes ativos" value={data.patients.length} /><Stat icon={FileText} label="Sessões em haver" value={data.packages.reduce((sum, p) => sum + remaining(p), 0)} /><Stat icon={WalletCards} label="Pagamentos pendentes" value={pending} warning /><Stat icon={CalendarDays} label="Sessões hoje" value={data.appointments.filter((a) => a.patientId !== null && a.scheduledAt.slice(0, 10) === today && !["Cancelado", "Faltou"].includes(a.status)).length} /></section><ClinicAlerts data={data} remaining={remaining} /><WaitingListPanel data={data} onOpen={() => setWaitlistOpen(true)} onSchedule={(patientId) => openAppointment("", patientId)} /><section className="grid gap-6 xl:grid-cols-[1.65fr_.75fr]"><PatientTable patients={data.patients} packages={data.packages} used={used} remaining={remaining} selectedId={selectedId} onSelect={setSelectedId} /><PatientCard patient={selected} pkg={selectedPackage} used={used} remaining={remaining} onOpen={(p) => openRecord(p.id)} onEdit={edit} onDelete={(p) => setDeleteTarget({ action: "patient.delete", id: p.id, label: p.name })} /></section></>}
        {view === "patients" && <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map((p) => { const pkg = data.packages.find((item) => item.patientId === p.id); return <button key={p.id} onClick={() => openRecord(p.id)} className="premium-card rounded-[22px] border bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-[#afd0c0]"><div className="flex items-center gap-4"><Avatar name={p.name} photo={p.profilePhoto} large /><div><h2 className="text-lg font-semibold">{p.name}</h2><p className="text-sm text-[#77847c]">{p.phone}</p></div></div><p className="mt-5 text-sm text-[#607068]">{p.notes || "Sem observações"}</p><div className="mt-5 flex justify-between border-t pt-4 text-sm"><span>{pkg?.name || "Sem pacote"}</span><strong className="text-[#08684e]">{pkg ? `${remaining(pkg)} em haver` : "Cadastrar"}</strong></div></button>; })}</div>}
        {view === "record" && selected && <PatientRecord patient={selected} data={data} tab={recordTab} setTab={setRecordTab} used={used} remaining={remaining} setModal={setModal} onEdit={() => edit(selected)} onEditSession={editSession} onEditPackage={editPackage} onEditAppointment={editAppointment} onDocumentsChanged={reloadClinic} onDeletePatient={() => setDeleteTarget({ action: "patient.delete", id: selected.id, label: selected.name })} onDelete={(action, id, label) => setDeleteTarget({ action, id, label })} />}
        {view === "packages" && <div className="grid gap-4 lg:grid-cols-2">{data.packages.map((pkg) => <PackageCard key={pkg.id} pkg={pkg} patient={name(pkg.patientId)} used={used(pkg.id)} remaining={remaining(pkg)} setModal={setModal} onEdit={() => editPackage(pkg)} onDelete={() => setDeleteTarget({ action: "package.delete", id: pkg.id, label: pkg.name })} />)}</div>}
        {view === "sessions" && <SessionsDirectory data={data} onCreate={(patientId) => { setSelectedId(patientId); setModal("session"); }} onOpenPatient={openRecord} onEdit={editSession} onDelete={(session) => setDeleteTarget({ action: "session.delete", id: session.id, label: `sessão de ${name(session.patientId)}` })} />}
        {view === "payments" && <FinanceDashboard data={data} name={name} onPayment={() => setModal("payment")} onExpense={() => setModal("expense")} onDeletePayment={(id, label) => setDeleteTarget({ action: "payment.delete", id, label })} onDeleteExpense={(id, label) => setDeleteTarget({ action: "expense.delete", id, label })} />}
        {view === "agenda" && <Agenda appointments={data.appointments} patients={data.patients} confirmationMessage={data.settings.confirmationMessage} name={name} onCreate={openAppointment} onCreateBlock={openBlock} onEditMessage={() => setModal("whatsappMessage")} onOpen={setSelectedAppointment} onStatus={(id, status) => mutate("appointment.status", { id, status }, "Agenda atualizada.")} onDelete={(a) => setDeleteTarget({ action: "appointment.delete", id: a.id, label: a.patientId === null ? a.title : `agendamento de ${name(a.patientId)}` })} />}
      </div></main><ActionModal modal={modal} setModal={setModal} data={data} remaining={remaining} submit={submit} saving={saving} editingPatient={editingPatient} editingSession={editingSession} editingPackage={editingPackage} editingAppointment={editingAppointment} preferredPatientId={modal === "appointment" ? preferredAppointmentPatientId : view === "record" || view === "sessions" ? selectedId : undefined} preferredAppointmentAt={preferredAppointmentAt} />
      <WaitingListDialog open={waitlistOpen} data={data} saving={saving} onClose={() => setWaitlistOpen(false)} onAdd={async (payload) => { const saved = await mutate("waiting-list.create", payload, "Paciente adicionada à lista de espera."); if (saved) setWaitlistOpen(false); }} onSchedule={(patientId) => { setWaitlistOpen(false); openAppointment("", patientId); }} onDelete={(id) => mutate("waiting-list.delete", { id }, "Paciente retirada da lista de espera.")} />
      <AppointmentActionsDialog appointment={selectedAppointment} patientName={selectedAppointment?.patientId === null ? selectedAppointment.title : name(selectedAppointment?.patientId ?? null)} saving={saving} onClose={() => setSelectedAppointment(null)} onEdit={editAppointment} onStatus={(appointment, status) => { setSelectedAppointment(null); mutate("appointment.status", { id: appointment.id, status }, "Agenda atualizada."); }} onDelete={(appointment) => { setSelectedAppointment(null); setDeleteTarget({ action: "appointment.delete", id: appointment.id, label: appointment.patientId === null ? appointment.title : `agendamento de ${name(appointment.patientId)}` }); }} />
      <DeleteDialog target={deleteTarget} saving={saving} onClose={() => setDeleteTarget(null)} onConfirm={() => deleteTarget && mutate(deleteTarget.action, { id: deleteTarget.id }, "Registro removido com sucesso.")} />
      <nav className="mobile-bottom-nav fixed inset-x-0 bottom-0 z-50 grid grid-cols-5 border-t border-[#dce6e0] bg-white/95 px-1 pb-[max(.45rem,env(safe-area-inset-bottom))] pt-1.5 shadow-[0_-12px_35px_rgba(23,70,52,.12)] backdrop-blur-xl lg:hidden">{mobileNav.map(([key, label, Icon]) => { const active = view === key || (key === "patients" && view === "record"); return <button key={key} onClick={() => go(key)} className={`flex min-h-14 flex-col items-center justify-center gap-1 rounded-xl text-[10px] font-medium ${active ? "bg-[#e7f4ed] text-[#076449]" : "text-[#738179]"}`}><Icon className={`size-5 ${active ? "stroke-[2.4]" : ""}`} /><span>{label}</span></button>; })}</nav>
  </div>;
}

function Stat({ icon: Icon, label, value, warning }: { icon: typeof Users; label: string; value: number; warning?: boolean }) { return <div className="metric-card premium-card rounded-2xl border bg-white p-5 shadow-sm"><div className="flex justify-between"><div><p className="text-sm text-[#66766d]">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></div><span className={`metric-icon grid size-12 place-items-center rounded-2xl ${warning ? "bg-[#fff2dc] text-[#96651f]" : "bg-[#e4f3eb] text-[#087052]"}`}><Icon className="size-5" /></span></div><p className="mt-3 text-xs text-[#8a958f]">Atualizado agora</p></div>; }
function WaitingListPanel({ data, onOpen, onSchedule }: { data: ClinicData; onOpen: () => void; onSchedule: (patientId: number) => void }) {
  const visible = data.waitingList.slice(0, 3);
  return <section className="premium-card mb-6 overflow-hidden rounded-[24px] border border-[#dfd2ad] bg-gradient-to-br from-white to-[#fffaf0] shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#eadfc3] px-5 py-4 sm:px-6"><div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-2xl bg-[#fff0c9] text-[#93651e]"><Bell className="size-5" /></span><div><h2 className="text-lg font-semibold">Lista de espera</h2><p className="text-sm text-[#746b58]">{data.waitingList.length ? `${data.waitingList.length} paciente${data.waitingList.length === 1 ? "" : "s"} aguardando uma vaga` : "Nenhuma paciente aguardando no momento"}</p></div></div><Button type="button" variant="outline" className="border-[#d7c38e] bg-white" onClick={onOpen}><Plus /> {data.waitingList.length ? "Ver lista completa" : "Adicionar paciente"}</Button></div>{visible.length ? <div className="grid divide-y divide-[#eee4ca] md:grid-cols-3 md:divide-x md:divide-y-0">{visible.map((entry) => { const patient = data.patients.find((item) => item.id === entry.patientId); if (!patient) return null; const phone = whatsappNumber(patient.phone); const message = encodeURIComponent(`Olá, ${patient.name}! Tudo bem? Surgiu uma possibilidade de horário para seu atendimento. Gostaria de verificar sua disponibilidade.`); return <article key={entry.id} className="p-5"><div className="flex items-center gap-3"><Avatar name={patient.name} photo={patient.profilePhoto} /><div className="min-w-0"><strong className="block truncate">{patient.name}</strong><p className="truncate text-xs text-[#7b7465]">{entry.preference || "Sem preferência informada"}</p></div></div><div className="mt-4 flex gap-2">{phone && <a href={`https://wa.me/${phone}?text=${message}`} target="_blank" rel="noreferrer" className="inline-flex h-9 flex-1 items-center justify-center gap-1.5 rounded-lg bg-[#25d366] px-2 text-xs font-semibold text-white"><MessageCircle className="size-4" /> WhatsApp</a>}<Button type="button" size="sm" className="flex-1 bg-[#08684e]" onClick={() => onSchedule(patient.id)}><CalendarDays /> Agendar</Button></div></article>; })}</div> : <button type="button" onClick={onOpen} className="flex w-full items-center justify-center gap-2 px-5 py-6 text-sm font-medium text-[#806828] transition hover:bg-[#fff8e7]"><Plus className="size-4" /> Adicionar a primeira paciente à lista de espera</button>}</section>;
}
function ClinicAlerts({ data, remaining }: { data: ClinicData; remaining: (pkg: ClinicPackage) => number }) { const patientName = (id: number | null) => id === null ? "Compromisso pessoal" : data.patients.find((patient) => patient.id === id)?.name || "Paciente"; const low = data.packages.filter((pkg) => pkg.status !== "Concluído" && remaining(pkg) === 1); const pending = data.packages.filter((pkg) => !paymentSettled(packagePaymentState(pkg))); const standalonePending = data.sessions.filter((session) => session.packageId === null && !paymentSettled(session.paymentStatus)); const todayAppointments = data.appointments.filter((appointment) => appointment.scheduledAt.slice(0, 10) === today && appointment.status === "Agendado"); const alerts = [...low.map((pkg) => `${patientName(pkg.patientId)} possui somente 1 sessão disponível.`), ...pending.map((pkg) => `${patientName(pkg.patientId)} possui pagamento ${packagePaymentState(pkg).toLowerCase()}${pkg.paymentDueDate ? ` (vencimento ${dateBR(pkg.paymentDueDate)})` : ""}.`), ...standalonePending.map((session) => `${patientName(session.patientId)} possui sessão avulsa ${session.paymentStatus.toLowerCase()}${session.paymentDueDate ? ` (vencimento ${dateBR(session.paymentDueDate)})` : ""}.`), ...todayAppointments.map((appointment) => `${patientName(appointment.patientId)} tem atendimento hoje às ${appointment.scheduledAt.slice(11, 16)}.`)].slice(0, 5); if (!alerts.length) return null; return <section className="premium-card mb-6 rounded-[22px] border border-[#ead9a9] bg-[#fffaf0] p-5"><div className="flex items-start gap-3"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-[#fff0c9] text-[#93651e]"><Bell className="size-5" /></span><div><h2 className="font-semibold">Atenção na rotina</h2><div className="mt-2 grid gap-1">{alerts.map((alert) => <p key={alert} className="text-sm text-[#675d45]">• {alert}</p>)}</div></div></div></section>; }
function FinanceDashboard({ data, name, onPayment, onExpense, onDeletePayment, onDeleteExpense }: { data: ClinicData; name: (id: number) => string; onPayment: () => void; onExpense: () => void; onDeletePayment: (id: number, label: string) => void; onDeleteExpense: (id: number, label: string) => void }) {
  const standaloneSessions = data.sessions.filter((item) => item.packageId === null);
  const income = data.payments.reduce((sum, item) => sum + item.amountCents, 0) + standaloneSessions.reduce((sum, item) => sum + item.coveredAmountCents, 0); const expenses = data.expenses.reduce((sum, item) => sum + item.amountCents, 0); const balance = income - expenses; const receivable = data.packages.reduce((sum, item) => sum + Math.max(0, item.totalAmountCents - item.paidAmountCents), 0) + standaloneSessions.reduce((sum, item) => sum + item.outstandingAmountCents, 0);
  const months = Array.from({ length: 6 }, (_, index) => { const date = new Date(); date.setMonth(date.getMonth() - (5 - index)); const key = date.toISOString().slice(0, 7); const label = new Intl.DateTimeFormat("pt-BR", { month: "short" }).format(date).replace(".", ""); const received = data.payments.filter((item) => item.paidAt.startsWith(key)).reduce((sum, item) => sum + item.amountCents, 0) + standaloneSessions.filter((item) => item.performedAt.startsWith(key)).reduce((sum, item) => sum + item.coveredAmountCents, 0); const spent = data.expenses.filter((item) => item.paidAt.startsWith(key)).reduce((sum, item) => sum + item.amountCents, 0); return { key, label, received, spent }; });
  const max = Math.max(1, ...months.flatMap((item) => [item.received, item.spent]));
  const methods = ["Pix", "Cartão", "Dinheiro", "Transferência"].map((method) => ({ method, total: data.payments.filter((item) => item.method === method).reduce((sum, item) => sum + item.amountCents, 0) + standaloneSessions.filter((item) => item.standalonePaymentMethod === method).reduce((sum, item) => sum + item.coveredAmountCents, 0) })).filter((item) => item.total > 0);
  return <div className="grid gap-6"><div className="flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={onExpense}><TrendingDown /> Nova despesa</Button><Button className="bg-[#08684e]" onClick={onPayment}><TrendingUp /> Nova entrada</Button></div><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><FinanceMetric icon={TrendingUp} label="Total recebido" value={money(income)} tone="green" /><FinanceMetric icon={TrendingDown} label="Despesas" value={money(expenses)} tone="red" /><FinanceMetric icon={WalletCards} label="Saldo atual" value={money(balance)} tone={balance >= 0 ? "green" : "red"} /><FinanceMetric icon={ReceiptText} label="A receber" value={money(receivable)} tone="gold" /></section><section className="grid gap-6 xl:grid-cols-[1.5fr_.7fr]"><div className="premium-card rounded-[24px] border bg-white p-6"><div className="flex items-center justify-between"><div><h2 className="text-xl font-semibold">Fluxo dos últimos meses</h2><p className="text-sm text-[#7b8881]">Entradas e despesas registradas</p></div><span className="grid size-11 place-items-center rounded-xl bg-[#e8f3ed] text-[#087052]"><BarChart3 /></span></div><div className="mt-8 flex h-56 items-end gap-3 sm:gap-6">{months.map((month) => <div key={month.key} className="flex h-full flex-1 flex-col justify-end"><div className="flex flex-1 items-end justify-center gap-1"><div title={`Entradas: ${money(month.received)}`} className="min-h-1 w-3 rounded-t-md bg-[#0b7558] sm:w-5" style={{ height: `${Math.max(3, month.received / max * 100)}%` }} /><div title={`Despesas: ${money(month.spent)}`} className="min-h-1 w-3 rounded-t-md bg-[#df9f74] sm:w-5" style={{ height: `${Math.max(3, month.spent / max * 100)}%` }} /></div><p className="mt-3 text-center text-xs font-medium capitalize text-[#77847c]">{month.label}</p></div>)}</div><div className="mt-5 flex justify-center gap-5 text-xs text-[#718078]"><span className="flex items-center gap-2"><i className="size-2.5 rounded-full bg-[#0b7558]" /> Entradas</span><span className="flex items-center gap-2"><i className="size-2.5 rounded-full bg-[#df9f74]" /> Despesas</span></div></div><div className="premium-card rounded-[24px] border bg-white p-6"><h2 className="text-xl font-semibold">Recebimentos</h2><p className="text-sm text-[#7b8881]">Por forma de pagamento</p><div className="mt-6 grid gap-4">{methods.length ? methods.map((item) => <div key={item.method}><div className="mb-2 flex justify-between text-sm"><span>{item.method}</span><strong>{money(item.total)}</strong></div><div className="h-2 overflow-hidden rounded-full bg-[#edf1ee]"><div className="h-full rounded-full bg-gradient-to-r from-[#0b7558] to-[#5fa98e]" style={{ width: `${item.total / income * 100}%` }} /></div></div>) : <EmptyState text="Sem recebimentos ainda." />}</div></div></section><section className="grid gap-6 xl:grid-cols-2"><History title="Entradas" button="Registrar entrada" onCreate={onPayment} onDelete={onDeletePayment} rows={data.payments.map((item) => ({ id: item.id, title: name(item.patientId), subtitle: `${item.method} · ${dateBR(item.paidAt)}`, value: money(item.amountCents), icon: TrendingUp }))} /><History title="Despesas" button="Nova despesa" onCreate={onExpense} onDelete={onDeleteExpense} rows={data.expenses.map((item) => ({ id: item.id, title: item.description, subtitle: `${item.category} · ${dateBR(item.paidAt)}`, value: `- ${money(item.amountCents)}`, icon: TrendingDown }))} /></section></div>;
}
function FinanceMetric({ icon: Icon, label, value, tone }: { icon: typeof TrendingUp; label: string; value: string; tone: "green" | "red" | "gold" }) { const styles = tone === "red" ? "bg-[#fff0eb] text-[#b65f43]" : tone === "gold" ? "bg-[#fff6df] text-[#9a6e1e]" : "bg-[#e5f3eb] text-[#087052]"; return <div className="premium-card rounded-[22px] border bg-white p-5"><div className="flex items-start justify-between"><div><p className="text-sm text-[#6e7d75]">{label}</p><p className="mt-3 text-2xl font-semibold tracking-tight">{value}</p></div><span className={`grid size-11 place-items-center rounded-xl ${styles}`}><Icon className="size-5" /></span></div></div>; }
function PatientTable({ patients, packages, used, remaining, selectedId, onSelect }: { patients: Patient[]; packages: ClinicPackage[]; used: (id: number) => number; remaining: (p: ClinicPackage) => number; selectedId: number; onSelect: (id: number) => void }) { return <div className="premium-card overflow-hidden rounded-2xl border bg-white shadow-sm"><div className="border-b px-6 py-5"><h2 className="text-xl font-semibold">Pacientes recentes</h2><p className="text-sm text-[#7b8881]">Pacotes, sessões e pagamentos em uma visão.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-[#fafbfa] text-xs uppercase text-[#7e8a83]"><tr><th className="px-6 py-3">Paciente</th><th className="px-4">Pacote</th><th className="px-4 text-center">Realizadas</th><th className="px-4 text-center">Restantes</th><th className="px-4">Pagamento</th><th /></tr></thead><tbody className="divide-y">{patients.map((p) => { const pkg = packages.find((item) => item.patientId === p.id); return <tr key={p.id} onClick={() => onSelect(p.id)} className={`cursor-pointer hover:bg-[#f5faf7] ${selectedId === p.id ? "bg-[#f0f8f4]" : ""}`}><td className="px-6 py-4"><div className="flex items-center gap-3"><Avatar name={p.name} photo={p.profilePhoto} /><div><strong>{p.name}</strong><p className="text-xs text-[#859087]">{p.phone}</p></div></div></td><td className="px-4">{pkg?.name || "Sem pacote"}</td><td className="px-4 text-center">{pkg ? used(pkg.id) : 0}</td><td className="px-4 text-center"><span className="rounded-full bg-[#e3f3ea] px-3 py-1 font-semibold text-[#08684e]">{pkg ? remaining(pkg) : 0}</span></td><td className="px-4">{pkg && <PaymentDeadlineStatus pkg={pkg} />}</td><td><ChevronRight className="size-4" /></td></tr>; })}</tbody></table></div></div>; }
function PatientCard({ patient, pkg, used, remaining, onOpen, onEdit, onDelete }: { patient?: Patient; pkg?: ClinicPackage; used: (id: number) => number; remaining: (p: ClinicPackage) => number; onOpen: (p: Patient) => void; onEdit: (p: Patient) => void; onDelete: (p: Patient) => void }) { if (!patient) return null; return <div className="premium-card rounded-[24px] border bg-white p-6 shadow-sm"><div className="flex items-start gap-4"><Avatar name={patient.name} photo={patient.profilePhoto} large /><div className="min-w-0 flex-1"><h2 className="text-xl font-semibold">{patient.name}</h2><p className="text-sm text-[#738078]">{patient.phone || "Sem telefone"}</p><p className="mt-1 truncate text-xs text-[#87928c]">{patient.notes || "Sem observações"}</p></div><div className="flex"><Button variant="ghost" size="icon" onClick={() => onEdit(patient)} title="Editar paciente"><Pencil className="size-4" /></Button><Button variant="ghost" size="icon" className="text-red-500 hover:text-red-600" onClick={() => onDelete(patient)} title="Remover paciente"><Trash2 className="size-4" /></Button></div></div><div className="my-6 border-t" />{pkg ? <><div className="flex justify-between"><div><p className="text-xs uppercase tracking-wider text-[#849087]">Pacote atual</p><strong>{pkg.name}</strong></div><Status value={pkg.status} /></div><div className="mt-6 flex justify-between text-sm"><strong>{used(pkg.id)} de {pkg.totalSessions} realizadas</strong><span>{remaining(pkg)} restantes</span></div><Progress value={used(pkg.id) / pkg.totalSessions * 100} className="mt-3 h-3" /><div className="mt-6 rounded-2xl bg-gradient-to-br from-[#eef8f2] to-[#f8fbf9] p-4"><div className="flex justify-between"><span>Pagamento</span><PaymentDeadlineStatus pkg={pkg} /></div><strong className="mt-2 block">{money(pkg.paidAmountCents)} de {money(pkg.totalAmountCents)}</strong><p className="text-xs text-[#819087]">Vencimento: {dateBR(pkg.paymentDueDate)} · Último pagamento: {dateBR(pkg.lastPaymentAt)}</p></div></> : <p className="rounded-xl bg-[#f7f9f7] p-4 text-sm text-[#718078]">Paciente sem pacote ativo.</p>}<Button className="mt-6 w-full bg-[#08684e] shadow-sm" onClick={() => onOpen(patient)}><FileText /> Abrir prontuário completo</Button></div>; }

function PatientRecord({ patient, data, tab, setTab, used, remaining, setModal, onEdit, onEditSession, onEditPackage, onEditAppointment, onDocumentsChanged, onDeletePatient, onDelete }: { patient: Patient; data: ClinicData; tab: RecordTab; setTab: (tab: RecordTab) => void; used: (id: number) => number; remaining: (pkg: ClinicPackage) => number; setModal: (modal: Modal) => void; onEdit: () => void; onEditSession: (session: Session) => void; onEditPackage: (pkg: ClinicPackage) => void; onEditAppointment: (appointment: Appointment) => void; onDocumentsChanged: () => Promise<void>; onDeletePatient: () => void; onDelete: (action: string, id: number, label: string) => void }) {
  const [month, setMonth] = useState("");
  const patientPackages = data.packages.filter((item) => item.patientId === patient.id);
  const allPatientSessions = data.sessions.filter((item) => item.patientId === patient.id);
  const patientSessions = allPatientSessions.filter((item) => !month || item.performedAt.startsWith(month));
  const patientPayments = data.payments.filter((item) => item.patientId === patient.id);
  const appointments = data.appointments.filter((item) => item.patientId === patient.id);
  const patientDocuments = data.documents.filter((item) => item.patientId === patient.id);
  const totalRemaining = patientPackages.reduce((sum, item) => sum + remaining(item), 0);
  const standaloneSessions = patientSessions.filter((item) => item.packageId === null);
  const totalPaid = patientPayments.reduce((sum, item) => sum + item.amountCents, 0) + standaloneSessions.reduce((sum, item) => sum + item.coveredAmountCents, 0);
  const totalPending = patientPackages.reduce((sum, item) => sum + Math.max(0, item.totalAmountCents - item.paidAmountCents), 0) + standaloneSessions.reduce((sum, item) => sum + item.outstandingAmountCents, 0);
  const paidSessionCount = patientSessions.filter((item) => paymentSettled(item.paymentStatus)).length;
  const pendingSessionCount = patientSessions.filter((item) => item.paymentStatus === "Pendente").length;
  const overdueSessionCount = patientSessions.filter((item) => item.paymentStatus === "Vencida").length;
  const whatsapp = whatsappNumber(patient.phone);
  const whatsappMessage = encodeURIComponent(`Olá, ${patient.name}! Tudo bem? Aqui é da Dra. Maria Carolini, fisioterapeuta.`);
  const tabs: [RecordTab, string][] = [["summary", "Resumo"], ["sessions", "Sessões"], ["packages", "Pacotes"], ["payments", "Pagamentos"], ["documents", "Documentos"], ["notes", "Observações"]];
  return <div className="grid gap-6">
    <section className="overflow-hidden rounded-[28px] bg-gradient-to-br from-[#064c3a] to-[#0a7256] text-white shadow-xl shadow-emerald-950/10"><div className="p-6 sm:p-8"><div className="flex flex-wrap items-start gap-5"><span style={patient.profilePhoto ? { backgroundImage: `url(${patient.profilePhoto})`, backgroundSize: "cover", backgroundPosition: "center" } : undefined} className="grid size-20 place-items-center rounded-[24px] bg-white/15 text-2xl font-semibold ring-1 ring-white/20">{!patient.profilePhoto && initials(patient.name)}</span><div className="min-w-[220px] flex-1"><div className="flex flex-wrap items-center gap-3"><h2 className="font-serif text-3xl font-semibold">{patient.name}</h2><span className="rounded-full bg-emerald-300/15 px-3 py-1 text-xs font-medium text-emerald-100">Prontuário ativo</span></div><div className="mt-2 flex flex-wrap items-center gap-2 text-sm text-white/70"><span>{patient.phone || "Sem telefone"}</span>{whatsapp && <a href={`https://wa.me/${whatsapp}?text=${whatsappMessage}`} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 rounded-full bg-[#25d366] px-3 py-1.5 text-xs font-semibold text-white shadow-sm transition hover:bg-[#1fb759]" aria-label={`Conversar com ${patient.name} pelo WhatsApp`}><MessageCircle className="size-3.5" /> WhatsApp</a>}{patient.email && <span className="basis-full text-white/55 sm:basis-auto">· {patient.email}</span>}</div><p className="mt-3 max-w-2xl text-sm text-white/55">{patient.notes || "Nenhuma observação geral cadastrada."}</p></div><div className="flex flex-wrap gap-2"><a href={`/relatorio/${patient.id}`} className="inline-flex h-9 items-center gap-2 rounded-lg border border-white/20 bg-white/10 px-3 text-sm font-medium text-white transition hover:bg-white/20"><Printer className="size-4" /> Relatório</a><Button className="border-white/20 bg-white/10 text-white hover:bg-white/20" onClick={onEdit}><Pencil /> Editar</Button><Button size="icon" className="border-white/20 bg-white/10 text-white hover:bg-red-500/70" onClick={onDeletePatient}><Trash2 /></Button></div></div><div className="mt-7 grid gap-3 sm:grid-cols-4"><RecordMetric label="Sessões realizadas" value={String(data.sessions.filter((item) => item.patientId === patient.id).length)} /><RecordMetric label="Sessões disponíveis" value={String(totalRemaining)} /><RecordMetric label="Total pago" value={money(totalPaid)} /><RecordMetric label="Valor pendente" value={money(totalPending)} /></div></div><div className="flex overflow-x-auto border-t border-white/10 bg-black/5 px-3 sm:px-6">{tabs.map(([key, label]) => <button key={key} onClick={() => setTab(key)} className={`whitespace-nowrap border-b-2 px-4 py-4 text-sm font-medium transition ${tab === key ? "border-[#ead59c] text-white" : "border-transparent text-white/55 hover:text-white"}`}>{label}</button>)}</div></section>

    {tab === "summary" && <div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><div className="grid gap-4"><SectionTitle title="Pacotes e sessões" subtitle="Situação atual do tratamento" action={<Button size="sm" onClick={() => setModal("package")} className="bg-[#08684e]"><Plus /> Novo pacote</Button>} />{patientPackages.length ? patientPackages.map((pkg) => <RecordPackage key={pkg.id} pkg={pkg} used={used(pkg.id)} remaining={remaining(pkg)} onEdit={() => onEditPackage(pkg)} />) : <div className="premium-card rounded-[22px] border bg-white"><EmptyState text="Nenhum pacote cadastrado." /></div>}</div><div className="grid content-start gap-4"><div className="premium-card rounded-[22px] border bg-white p-5"><SectionTitle title="Ações rápidas" subtitle="Registre sem sair do prontuário" /><div className="mt-5 grid gap-2"><Button className="bg-[#08684e]" onClick={() => setModal("session")}><Stethoscope /> Registrar sessão</Button><Button variant="outline" onClick={() => setModal("payment")}><Banknote /> Registrar pagamento</Button><Button variant="outline" onClick={() => setModal("appointment")}><CalendarDays /> Agendar atendimento</Button></div></div><div className="premium-card rounded-[22px] border bg-white p-5"><SectionTitle title="Próximos atendimentos" subtitle={`${appointments.length} registro(s)`} /><div className="mt-4 grid gap-3">{appointments.slice(0, 4).map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-[#f5f9f6] p-3 text-sm"><div><strong>{dateBR(item.scheduledAt)}</strong><p className="text-[#748179]">{item.scheduledAt.slice(11, 16)} · {item.durationMinutes} min</p></div><div className="flex items-center gap-1"><Status value={item.status} /><Button type="button" variant="ghost" size="sm" className="h-8 px-2 text-[#08684e]" onClick={() => onEditAppointment(item)}><Pencil className="size-3.5" /> Editar</Button></div></div>)}{!appointments.length && <p className="text-sm text-[#7d8a83]">Nenhum agendamento.</p>}</div></div></div></div>}

    {tab === "sessions" && <div className="grid gap-5"><div className="flex flex-wrap items-end justify-between gap-3"><SectionTitle title="Histórico de sessões" subtitle="Organizado em ciclos de 1 a 5" /><div className="flex gap-2"><label className="grid gap-1 text-xs text-[#748179]">Filtrar por mês<Input type="month" value={month} onChange={(event) => setMonth(event.target.value)} className="h-10 bg-white" /></label><Button className="mt-auto bg-[#08684e]" onClick={() => setModal("session")}><Plus /> Nova sessão</Button></div></div><SessionPaymentSummary paid={paidSessionCount} pending={pendingSessionCount} overdue={overdueSessionCount} />{patientSessions.length ? <SessionCycleList sessions={patientSessions} allSessions={allPatientSessions} packageName={(session) => session.packageId === null ? "Sessão avulsa" : data.packages.find((item) => item.id === session.packageId)?.name || "Pacote"} onEdit={onEditSession} onDelete={(session) => onDelete("session.delete", session.id, `sessão de ${dateBR(session.performedAt)}`)} /> : <div className="premium-card rounded-[22px] border bg-white"><EmptyState text="Nenhuma sessão encontrada neste período." /></div>}</div>}

    {tab === "packages" && <div className="grid gap-4 lg:grid-cols-2">{patientPackages.map((pkg) => <PackageCard key={pkg.id} pkg={pkg} patient={patient.name} used={used(pkg.id)} remaining={remaining(pkg)} setModal={setModal} onEdit={() => onEditPackage(pkg)} onDelete={() => onDelete("package.delete", pkg.id, pkg.name)} />)}{!patientPackages.length && <div className="premium-card rounded-[22px] border bg-white lg:col-span-2"><EmptyState text="Nenhum pacote cadastrado." /></div>}</div>}

    {tab === "payments" && <div className="grid gap-6"><section className="grid gap-4 sm:grid-cols-3"><FinanceMetric icon={TrendingUp} label="Total pago" value={money(totalPaid)} tone="green" /><FinanceMetric icon={ReceiptText} label="A pagar" value={money(totalPending)} tone="gold" /><FinanceMetric icon={WalletCards} label="Último pagamento" value={dateBR(patientPayments[0]?.paidAt)} tone="green" /></section><History title="Pagamentos do paciente" button="Registrar pagamento" onCreate={() => setModal("payment")} onDelete={(id, label) => onDelete("payment.delete", id, label)} rows={patientPayments.map((item) => ({ id: item.id, title: data.packages.find((pkg) => pkg.id === item.packageId)?.name || patient.name, subtitle: `${item.method} · ${dateBR(item.paidAt)}`, value: money(item.amountCents), icon: TrendingUp }))} /></div>}

    {tab === "documents" && <PatientDocuments patient={patient} documents={patientDocuments} onChanged={onDocumentsChanged} />}

    {tab === "notes" && <div className="premium-card rounded-[24px] border bg-white p-6"><div className="flex items-start justify-between gap-4"><SectionTitle title="Observações gerais" subtitle="Informações permanentes do prontuário" /><Button variant="outline" onClick={onEdit}><Pencil /> Editar</Button></div><div className="mt-6 min-h-40 whitespace-pre-wrap rounded-2xl bg-[#f7faf8] p-5 leading-relaxed text-[#52645b]">{patient.notes || "Nenhuma observação geral cadastrada para este paciente."}</div></div>}
  </div>;
}

function PatientDocuments({ patient, documents, onChanged }: { patient: Patient; documents: PatientDocument[]; onChanged: () => Promise<void> }) {
  const [uploading, setUploading] = useState(false);
  const [removingId, setRemovingId] = useState<number | null>(null);
  const [category, setCategory] = useState("Documento");
  async function uploadDocument(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const input = form.elements.namedItem("file") as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) { toast.error("Escolha um documento para anexar."); return; }
    if (file.size > 8 * 1024 * 1024) { toast.error("O documento deve ter no máximo 8 MB."); return; }
    setUploading(true);
    try {
      const body = new FormData();
      body.set("patientId", String(patient.id)); body.set("category", category); body.set("file", file);
      const response = await fetch("/api/documents", { method: "POST", body });
      const result = await response.json() as { error?: string };
      if (!response.ok) throw new Error(result.error || "Não foi possível anexar o documento.");
      await onChanged(); form.reset(); setCategory("Documento"); toast.success("Documento protegido e salvo com sucesso.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível anexar o documento."); }
    finally { setUploading(false); }
  }
  async function archiveDocument(document: PatientDocument) {
    if (!window.confirm(`Remover “${document.name}” da lista? O arquivo ficará preservado no histórico de segurança.`)) return;
    setRemovingId(document.id);
    try {
      const response = await fetch(`/api/documents/${document.id}`, { method: "DELETE" });
      const result = await response.json() as { error?: string };
      if (!response.ok) throw new Error(result.error || "Não foi possível remover o documento.");
      await onChanged(); toast.success("Documento removido da lista e preservado no histórico.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível remover o documento."); }
    finally { setRemovingId(null); }
  }
  return <div className="grid gap-5">
    <div className="premium-card rounded-[24px] border bg-white p-5 sm:p-6"><div className="flex items-start gap-3"><span className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#e8f3ed] text-[#087052]"><ShieldCheck className="size-5" /></span><div><h3 className="text-xl font-semibold">Documentos protegidos</h3><p className="mt-1 text-sm leading-relaxed text-[#718078]">Os arquivos ficam vinculados somente ao prontuário de {patient.name}, armazenados no banco do sistema e protegidos pelo acesso da clínica.</p></div></div><form onSubmit={uploadDocument} className="mt-6 grid gap-4 rounded-2xl bg-[#f6f9f7] p-4 sm:grid-cols-[180px_1fr_auto] sm:items-end"><div className="grid gap-2"><Label htmlFor="document-category">Tipo do documento</Label><NativeSelect id="document-category" value={category} onChange={(event) => setCategory(event.target.value)} className="h-11 w-full"><NativeSelectOption>Documento</NativeSelectOption><NativeSelectOption>Exame</NativeSelectOption><NativeSelectOption>Laudo</NativeSelectOption><NativeSelectOption>Receita</NativeSelectOption><NativeSelectOption>Atestado</NativeSelectOption><NativeSelectOption>Contrato</NativeSelectOption><NativeSelectOption>Foto</NativeSelectOption><NativeSelectOption>Outro</NativeSelectOption></NativeSelect></div><div className="grid gap-2"><Label htmlFor="patient-document">Escolher arquivo</Label><Input id="patient-document" name="file" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx" required className="h-11 bg-white file:mr-3 file:border-0 file:bg-transparent file:font-medium" /><p className="text-xs text-[#718078]">PDF, imagem ou Word · máximo de 8 MB.</p></div><Button disabled={uploading} className="h-11 bg-[#08684e] hover:bg-[#07533f]"><Upload /> {uploading ? "Salvando..." : "Anexar e salvar"}</Button></form></div>
    <div className="premium-card overflow-hidden rounded-[24px] border bg-white"><div className="border-b px-5 py-4 sm:px-6"><SectionTitle title="Arquivos do paciente" subtitle={`${documents.length} documento(s) salvo(s)`} /></div>{documents.length ? <div className="divide-y">{documents.map((document) => <div key={document.id} className="flex flex-wrap items-center gap-3 px-5 py-4 sm:px-6"><span className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#edf5f0] text-[#087052]"><FileText className="size-5" /></span><div className="min-w-0 flex-1"><strong className="block truncate">{document.name}</strong><p className="text-xs text-[#75837b]">{document.category} · {formatFileSize(document.sizeBytes)} · salvo em {dateBR(document.createdAt)}</p></div><div className="flex gap-1"><Button variant="outline" size="sm" asChild><a href={`/api/documents/${document.id}`} target="_blank" rel="noreferrer"><Eye className="size-4" /> Abrir</a></Button><Button variant="ghost" size="icon" className="text-red-500 hover:text-red-600" disabled={removingId === document.id} onClick={() => archiveDocument(document)} title="Remover da lista"><Trash2 className="size-4" /></Button></div></div>)}</div> : <EmptyState text="Nenhum documento anexado a este prontuário." />}</div>
  </div>;
}

function formatFileSize(bytes: number) { if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1).replace(".0", "")} KB`; return `${(bytes / 1024 / 1024).toFixed(1).replace(".0", "")} MB`; }

function RecordMetric({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl border border-white/10 bg-white/10 p-4 backdrop-blur"><p className="text-xs text-white/55">{label}</p><strong className="mt-1 block text-xl">{value}</strong></div>; }
function SectionTitle({ title, subtitle, action }: { title: string; subtitle: string; action?: React.ReactNode }) { return <div className="flex items-center justify-between gap-3"><div><h3 className="text-xl font-semibold">{title}</h3><p className="text-sm text-[#7b8881]">{subtitle}</p></div>{action}</div>; }
function RecordPackage({ pkg, used, remaining, onEdit }: { pkg: ClinicPackage; used: number; remaining: number; onEdit?: () => void }) { const paidSessions = pkg.totalAmountCents > 0 ? Math.min(pkg.totalSessions, Math.floor(pkg.paidAmountCents / pkg.totalAmountCents * pkg.totalSessions)) : 0; return <div className="premium-card rounded-[22px] border bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="font-semibold">{pkg.name}</h3><Status value={pkg.status} /></div><p className="mt-1 text-sm text-[#7b8881]">Contratado em {dateBR(pkg.purchasedAt)}</p></div><div className="flex items-center gap-2"><PaymentDeadlineStatus pkg={pkg} />{onEdit && <Button type="button" variant="outline" size="sm" onClick={onEdit}><Pencil className="size-4" /> Editar pacote</Button>}</div></div><div className="mt-5 flex justify-between text-sm"><strong>{used} realizadas</strong><span>{remaining} disponíveis</span></div><Progress value={used / pkg.totalSessions * 100} className="mt-2 h-3" /><div className="mt-5 grid gap-3 rounded-2xl bg-[#f6f9f7] p-4 text-sm sm:grid-cols-4"><div><span className="text-[#7b8881]">Pacote</span><strong className="block">{pkg.totalSessions} sessões</strong></div><div><span className="text-[#7b8881]">Cobertas pelo pagamento</span><strong className="block">{paidSessions} sessões</strong></div><div><span className="text-[#7b8881]">Pago</span><strong className="block">{money(pkg.paidAmountCents)}</strong></div><div><span className="text-[#7b8881]">Pendente</span><strong className="block">{money(Math.max(0, pkg.totalAmountCents - pkg.paidAmountCents))}</strong></div></div><div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-xs text-[#829087]"><span>Último pagamento: {dateBR(pkg.lastPaymentAt)} · {pkg.paymentMethod}</span><span className="font-semibold">Vencimento: {dateBR(pkg.paymentDueDate)}</span></div></div>; }
function SessionRecord({ session, number, packageName, patient, onOpenPatient, onEdit, onDelete }: { session: Session; number?: number; packageName: string; patient?: Patient; onOpenPatient?: () => void; onEdit: () => void; onDelete: () => void }) {
  const [open, setOpen] = useState(false);
  const hasDetails = Boolean(session.measurementIn || session.measurementOut || session.notes || session.occurrences);
  return <article className="premium-card overflow-hidden rounded-[20px] border bg-white shadow-sm transition hover:border-[#c4dacf]">
    <div className="flex items-center gap-3 p-4 sm:gap-4 sm:p-5">
      {patient ? <Avatar name={patient.name} photo={patient.profilePhoto} /> : <span className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#e5f3eb] font-semibold text-[#087052]">{number}ª</span>}
      <button type="button" className="min-w-0 flex-1 text-left" onClick={() => setOpen((value) => !value)}>
        <div className="flex flex-wrap items-center gap-2"><h3 className="font-semibold">{patient?.name || session.procedureType || "Sessão registrada"}</h3><SessionPaymentStatus session={session} />{session.occurrences && <span className="rounded-full bg-amber-100 px-2.5 py-1 text-[11px] font-medium text-amber-800">Com intercorrência</span>}{(session.measurementIn || session.measurementOut) && <span className="rounded-full bg-[#eaf5ef] px-2.5 py-1 text-[11px] font-medium text-[#087052]">Com medidas</span>}</div>
        <p className="mt-1 truncate text-sm text-[#75837b]">{patient && `${session.procedureType || "Sessão registrada"} · `}{dateBR(session.performedAt)} · {packageName}</p>
      </button>
      {patient && onOpenPatient && <Button variant="ghost" size="sm" className="hidden text-[#087052] sm:inline-flex" onClick={onOpenPatient}>Prontuário</Button>}
      <button type="button" onClick={() => setOpen((value) => !value)} aria-label={open ? "Fechar detalhes" : "Ver detalhes"} className="grid size-9 shrink-0 place-items-center rounded-full text-[#607168] transition hover:bg-[#eef5f1]"><ChevronDown className={`size-5 transition-transform ${open ? "rotate-180" : ""}`} /></button>
    </div>
    {open && <div className="border-t bg-[#fbfcfb] px-4 py-5 sm:px-5">
      <div className={`mb-4 grid gap-3 rounded-xl border p-4 sm:grid-cols-4 ${session.paymentStatus === "Paga" ? "border-emerald-200 bg-emerald-50/70" : session.paymentStatus === "Sem cobrança" ? "border-slate-200 bg-slate-50" : session.paymentStatus === "Vencida" ? "border-rose-200 bg-rose-50/70" : "border-amber-200 bg-amber-50/70"}`}><div><p className="text-xs uppercase tracking-wide text-[#78857e]">Valor da sessão</p><strong>{money(session.sessionValueCents || 0)}</strong></div><div><p className="text-xs uppercase tracking-wide text-[#78857e]">Valor coberto</p><strong>{money(session.coveredAmountCents || 0)}</strong></div><div><p className="text-xs uppercase tracking-wide text-[#78857e]">Falta pagar</p><strong>{money(session.outstandingAmountCents || 0)}</strong></div><div><p className="text-xs uppercase tracking-wide text-[#78857e]">Vencimento</p><strong>{session.paymentStatus === "Sem cobrança" ? "Não se aplica" : dateBR(session.paymentDueDate)}</strong></div></div>
      {!hasDetails && <p className="rounded-xl bg-white p-4 text-sm text-[#75837b]">Esta sessão não possui observações adicionais.</p>}
      {(session.measurementIn || session.measurementOut) && <div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-white p-4"><p className="text-xs uppercase tracking-wide text-[#849087]">Medida de entrada</p><strong className="mt-1 block">{session.measurementIn || "Não informada"}</strong></div><div className="rounded-xl bg-[#eef7f2] p-4"><p className="text-xs uppercase tracking-wide text-[#849087]">Medida de saída</p><strong className="mt-1 block">{session.measurementOut || "Não informada"}</strong></div></div>}
      {session.notes && <div className="mt-4"><p className="text-xs font-semibold uppercase tracking-wide text-[#849087]">Evolução e observações</p><p className="mt-1 whitespace-pre-wrap text-sm leading-relaxed text-[#53645b]">{session.notes}</p></div>}
      {session.occurrences && <div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4"><p className="text-xs font-semibold uppercase tracking-wide text-amber-800">Intercorrências</p><p className="mt-1 whitespace-pre-wrap text-sm text-amber-900">{session.occurrences}</p></div>}
      <div className="mt-5 flex flex-wrap justify-end gap-2"><Button variant="outline" size="sm" onClick={onEdit}><Pencil className="size-4" /> Corrigir sessão</Button><Button variant="ghost" size="sm" className="text-red-500 hover:text-red-600" onClick={onDelete}><Trash2 className="size-4" /> Cancelar registro</Button></div>
    </div>}
  </article>;
}
function SessionCycleList({ sessions, allSessions, packageName, onEdit, onDelete }: { sessions: Session[]; allSessions: Session[]; packageName: (session: Session) => string; onEdit: (session: Session) => void; onDelete: (session: Session) => void }) {
  return <div className="grid gap-3">{sessions.map((session, index) => { const info = sessionCycle(allSessions, session); const previousCycle = index > 0 ? sessionCycle(allSessions, sessions[index - 1]).cycle : null; const showDivider = info.cycle !== previousCycle; return <Fragment key={session.id}>{showDivider && <div className="session-cycle-divider"><span>Ciclo {info.cycle}</span><small>Sessões de 1 a 5</small></div>}<SessionRecord session={session} number={info.number} packageName={packageName(session)} onEdit={() => onEdit(session)} onDelete={() => onDelete(session)} /></Fragment>; })}</div>;
}
function SessionPaymentStatus({ session }: { session: Session }) { const value = session.paymentStatus || "Pendente"; const styles = value === "Paga" ? "bg-emerald-100 text-emerald-800" : value === "Sem cobrança" ? "bg-slate-100 text-slate-700" : value === "Vencida" ? "bg-rose-100 text-rose-800" : "bg-amber-100 text-amber-800"; return <span className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${styles}`}>{value}{session.isPartialPayment ? " · parcial" : ""}</span>; }
function SessionPaymentSummary({ paid, pending, overdue }: { paid: number; pending: number; overdue: number }) { return <div className="premium-card grid overflow-hidden rounded-[20px] border bg-white sm:grid-cols-3"><div className="border-b p-4 sm:border-b-0 sm:border-r"><p className="text-xs font-medium uppercase tracking-wide text-emerald-700">Resolvidas</p><strong className="mt-1 block text-2xl text-emerald-800">{paid}</strong><span className="text-xs text-emerald-700">Pagas ou sem cobrança</span></div><div className="border-b p-4 sm:border-b-0 sm:border-r"><p className="text-xs font-medium uppercase tracking-wide text-amber-700">Pendentes</p><strong className="mt-1 block text-2xl text-amber-800">{pending}</strong><span className="text-xs text-amber-700">Dentro do prazo</span></div><div className="p-4"><p className="text-xs font-medium uppercase tracking-wide text-rose-700">Vencidas</p><strong className="mt-1 block text-2xl text-rose-800">{overdue}</strong><span className="text-xs text-rose-700">Prazo ultrapassado</span></div></div>; }
function PaymentDeadlineStatus({ pkg }: { pkg: ClinicPackage }) { const value = packagePaymentState(pkg); const styles = value === "Pago" ? "bg-emerald-100 text-emerald-800" : value === "Sem cobrança" ? "bg-slate-100 text-slate-700" : value === "Vencido" ? "bg-rose-100 text-rose-800" : "bg-amber-100 text-amber-800"; return <span className={`rounded-full px-3 py-1 text-xs font-semibold ${styles}`}>{value}</span>; }
function PackageCard({ pkg, patient, used, remaining, setModal, onEdit, onDelete }: { pkg: ClinicPackage; patient: string; used: number; remaining: number; setModal: (m: Modal) => void; onEdit: () => void; onDelete: () => void }) { return <div className="premium-card rounded-[24px] border bg-white p-6 shadow-sm"><div className="flex justify-between gap-3"><div><p className="text-sm text-[#728078]">{patient}</p><h2 className="text-xl font-semibold">{pkg.name}</h2></div><div className="flex items-start gap-1"><PaymentDeadlineStatus pkg={pkg} /><Button variant="ghost" size="icon" onClick={onEdit} title="Editar pacote"><Pencil className="size-4" /></Button><Button variant="ghost" size="icon" className="text-red-500" onClick={onDelete} title="Remover pacote"><Trash2 className="size-4" /></Button></div></div><div className="mt-6 flex items-end justify-between"><div><p className="text-3xl font-semibold text-[#08684e]">{remaining}</p><p className="text-sm text-[#748179]">sessões em haver</p></div><p className="text-sm"><strong>{used}</strong> de {pkg.totalSessions}</p></div><Progress value={used / pkg.totalSessions * 100} className="mt-4 h-3" /><div className="mt-5 grid grid-cols-2 gap-3 rounded-2xl bg-[#f7f9f7] p-4 text-sm"><div>Valor<br /><strong>{money(pkg.totalAmountCents)}</strong></div><div>Pago<br /><strong>{money(pkg.paidAmountCents)}</strong></div><div>Contratado<br /><strong>{dateBR(pkg.purchasedAt)}</strong></div><div>Vencimento<br /><strong>{dateBR(pkg.paymentDueDate)}</strong></div></div><div className="mt-5 grid gap-2 sm:grid-cols-3"><Button className="bg-[#08684e]" onClick={() => setModal("session")}>Sessão</Button><Button variant="outline" onClick={() => setModal("payment")}>Pagamento</Button><Button variant="outline" onClick={onEdit}><Pencil /> Editar pacote</Button></div></div>; }
function SessionsDirectory({ data, onCreate, onOpenPatient, onEdit, onDelete }: { data: ClinicData; onCreate: (patientId: number) => void; onOpenPatient: (id: number) => void; onEdit: (session: Session) => void; onDelete: (session: Session) => void }) {
  const [patientId, setPatientId] = useState("");
  const [searchInput, setSearchInput] = useState("");
  const [patientQuery, setPatientQuery] = useState("");
  const [month, setMonth] = useState("");
  const [procedure, setProcedure] = useState("");
  const patient = data.patients.find((item) => item.id === Number(patientId));
  const patientSessions = patient ? data.sessions.filter((session) => session.patientId === patient.id) : [];
  const patientPackages = patient ? data.packages.filter((pkg) => pkg.patientId === patient.id) : [];
  const currentPackage = patientPackages.find((pkg) => pkg.status !== "Concluído") || patientPackages[0];
  const used = (packageId: number) => data.sessions.filter((session) => session.packageId === packageId).length;
  const remaining = (pkg: ClinicPackage) => Math.max(0, pkg.totalSessions - used(pkg.id));
  const procedures = Array.from(new Set(patientSessions.map((session) => session.procedureType).filter(Boolean))).sort();
  const sessions = patientSessions.filter((session) => (!month || session.performedAt.startsWith(month)) && (!procedure || session.procedureType === procedure));
  const filteredPatients = data.patients.filter((item) => `${item.name} ${item.phone} ${item.email}`.toLowerCase().includes(patientQuery.toLowerCase())).sort((a, b) => a.name.localeCompare(b.name));
  const filtersActive = Boolean(month || procedure);
  const paidSessions = sessions.filter((item) => paymentSettled(item.paymentStatus)).length;
  const pendingSessions = sessions.filter((item) => item.paymentStatus === "Pendente").length;
  const overdueSessions = sessions.filter((item) => item.paymentStatus === "Vencida").length;
  const selectPatient = (value: string) => { setPatientId(value); setMonth(""); setProcedure(""); };
  return <div className="grid gap-5">
    <div className="premium-card rounded-[22px] border bg-white p-5">
      <div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-xl bg-[#e5f3eb] text-[#087052]"><Users className="size-5" /></span><div><h2 className="text-lg font-semibold">Pacientes e sessões</h2><p className="text-sm text-[#75837b]">Pesquise ou clique em um paciente para abrir todas as informações.</p></div></div>
      <form className="mt-5 flex flex-col gap-2 sm:flex-row" onSubmit={(event) => { event.preventDefault(); setPatientQuery(searchInput.trim()); }}><div className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#718078]" /><Input value={searchInput} onChange={(event) => setSearchInput(event.target.value)} placeholder="Digite o nome, telefone ou e-mail..." className="h-11 pl-10" /></div><Button type="submit" className="bg-[#08684e]"><Search className="size-4" /> Pesquisar</Button>{patientQuery && <Button type="button" variant="ghost" onClick={() => { setSearchInput(""); setPatientQuery(""); }}>Mostrar todos</Button>}</form>
      <div className="mt-5 grid max-h-[430px] gap-3 overflow-y-auto pr-1 md:grid-cols-2 xl:grid-cols-3">{filteredPatients.map((item) => { const itemSessions = data.sessions.filter((session) => session.patientId === item.id); const itemPackages = data.packages.filter((pkg) => pkg.patientId === item.id); const itemCurrentPackage = itemPackages.find((pkg) => pkg.status !== "Concluído") || itemPackages[0]; const available = itemPackages.reduce((sum, pkg) => sum + remaining(pkg), 0); const selected = item.id === patient?.id; return <button type="button" key={item.id} onClick={() => selectPatient(String(item.id))} className={`rounded-2xl border p-4 text-left transition hover:-translate-y-0.5 hover:border-[#8fbea8] hover:shadow-sm ${selected ? "border-[#087052] bg-[#eff8f3] ring-1 ring-[#087052]" : "bg-[#fbfcfb]"}`}><div className="flex items-center gap-3"><Avatar name={item.name} /><div className="min-w-0 flex-1"><strong className="block truncate">{item.name}</strong><p className="truncate text-xs text-[#7b8881]">{item.phone || "Sem telefone"}</p></div><ChevronRight className="size-4 text-[#6f7e76]" /></div><div className="mt-4 grid grid-cols-3 gap-2 border-t pt-3 text-center"><div><strong className="block text-[#087052]">{itemSessions.length}</strong><span className="text-[11px] text-[#7d8982]">realizadas</span></div><div><strong className="block text-[#087052]">{available}</strong><span className="text-[11px] text-[#7d8982]">disponíveis</span></div><div><strong className="block truncate text-xs text-[#344a40]">{itemCurrentPackage ? dateBR(itemSessions[0]?.performedAt) : "—"}</strong><span className="text-[11px] text-[#7d8982]">última</span></div></div></button>; })}</div>
      {!filteredPatients.length && <div className="mt-4 rounded-2xl border border-dashed"><EmptyState text="Nenhum paciente encontrado com essa pesquisa." /></div>}
    </div>
    {!patient && <div className="premium-card rounded-[24px] border border-dashed bg-white py-8"><EmptyState text="Clique em um paciente da lista para visualizar todas as sessões e opções." /></div>}
    {patient && <>
      <section className="overflow-hidden rounded-[26px] bg-gradient-to-br from-[#07533f] to-[#0a7055] text-white shadow-lg shadow-emerald-950/10">
        <div className="flex flex-wrap items-center gap-4 p-6 sm:p-7"><Avatar name={patient.name} photo={patient.profilePhoto} large /><div className="min-w-[220px] flex-1"><p className="text-sm text-white/60">Paciente selecionado</p><h2 className="font-serif text-2xl font-semibold">{patient.name}</h2><p className="mt-1 text-sm text-white/70">{patient.phone || "Sem telefone"}{patient.email && ` · ${patient.email}`}</p></div><Button variant="outline" className="border-white/20 bg-white/10 text-white hover:bg-white/20 hover:text-white" onClick={() => onOpenPatient(patient.id)}><FileText /> Abrir prontuário completo</Button></div>
        <div className="grid border-t border-white/10 sm:grid-cols-3"><div className="p-5 sm:border-r sm:border-white/10"><p className="text-xs text-white/55">Sessões realizadas</p><strong className="mt-1 block text-2xl">{patientSessions.length}</strong></div><div className="p-5 sm:border-r sm:border-white/10"><p className="text-xs text-white/55">Sessões disponíveis</p><strong className="mt-1 block text-2xl">{patientPackages.reduce((sum, pkg) => sum + remaining(pkg), 0)}</strong></div><div className="p-5"><p className="text-xs text-white/55">Última sessão</p><strong className="mt-1 block text-2xl">{dateBR(patientSessions[0]?.performedAt)}</strong></div></div>
      </section>
      {currentPackage && <RecordPackage pkg={currentPackage} used={used(currentPackage.id)} remaining={remaining(currentPackage)} />}
      <div className="premium-card rounded-[22px] border bg-white p-5">
        <div className="flex flex-wrap items-end gap-3"><div className="min-w-[190px] flex-1"><Label>Procedimento</Label><NativeSelect value={procedure} onChange={(event) => setProcedure(event.target.value)} className="mt-2 h-11 w-full"><NativeSelectOption value="">Todos os procedimentos</NativeSelectOption>{procedures.map((item) => <NativeSelectOption key={item} value={item}>{item}</NativeSelectOption>)}</NativeSelect></div><div><Label>Mês</Label><Input type="month" value={month} onChange={(event) => setMonth(event.target.value)} className="mt-2 h-11 bg-white" /></div>{filtersActive && <Button variant="ghost" onClick={() => { setMonth(""); setProcedure(""); }}>Limpar filtros</Button>}<Button className="bg-[#08684e]" onClick={() => onCreate(patient.id)}><Plus /> Registrar nova sessão</Button></div>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t pt-4 text-sm text-[#718078]"><span>{sessions.length} {sessions.length === 1 ? "sessão encontrada" : "sessões encontradas"}</span><span>Clique em uma sessão para consultar a evolução</span></div>
      </div>
      <SessionPaymentSummary paid={paidSessions} pending={pendingSessions} overdue={overdueSessions} />
      {sessions.length ? <SessionCycleList sessions={sessions} allSessions={patientSessions} packageName={(session) => session.packageId === null ? "Sessão avulsa" : data.packages.find((pkg) => pkg.id === session.packageId)?.name || "Pacote"} onEdit={onEdit} onDelete={onDelete} /> : <div className="premium-card rounded-[22px] border bg-white"><EmptyState text="Nenhuma sessão encontrada para este paciente com os filtros escolhidos." /></div>}
    </>}
  </div>;
}
function History({ title, button, onCreate, onDelete, rows }: { title: string; button: string; onCreate: () => void; onDelete: (id: number, label: string) => void; rows: { id: number; title: string; subtitle: string; value: string; icon: typeof Stethoscope }[] }) { return <div className="premium-card overflow-hidden rounded-[24px] border bg-white"><div className="flex items-center justify-between border-b p-6"><h2 className="text-xl font-semibold">{title}</h2><Button onClick={onCreate} className="bg-[#08684e]"><Plus />{button}</Button></div><div className="divide-y">{rows.length ? rows.map((row) => <div key={row.id} className="group flex items-center gap-4 px-6 py-4 hover:bg-[#f8fbf9]"><span className="grid size-11 place-items-center rounded-xl bg-[#e5f3eb] text-[#087052]"><row.icon className="size-5" /></span><div className="flex-1"><strong>{row.title}</strong><p className="text-sm text-[#78857d]">{row.subtitle}</p></div><strong className="text-[#08684e]">{row.value}</strong><Button variant="ghost" size="icon" className="text-red-500 opacity-60 transition group-hover:opacity-100" onClick={() => onDelete(row.id, `${title.toLowerCase()} de ${row.title}`)}><Trash2 className="size-4" /></Button></div>) : <EmptyState text="Nenhum registro ainda." />}</div></div>; }
const localDateKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const addCalendarDays = (date: Date, amount: number) => { const next = new Date(date); next.setDate(next.getDate() + amount); return next; };
const weekStart = (date: Date) => { const next = new Date(date); next.setHours(0, 0, 0, 0); next.setDate(next.getDate() - ((next.getDay() + 6) % 7)); return next; };
const appointmentTone = (status: string) => status === "Bloqueado" ? "calendar-blocked" : status === "Concluído" ? "calendar-done" : status === "Confirmado" ? "calendar-confirmed" : status === "Cancelado" || status === "Faltou" ? "calendar-cancelled" : "calendar-scheduled";
const appointmentStartMinutes = (appointment: Appointment) => Number(appointment.scheduledAt.slice(11, 13)) * 60 + Number(appointment.scheduledAt.slice(14, 16));
const appointmentBlocksAgenda = (appointment: Appointment) => !["Cancelado", "Faltou"].includes(appointment.status);
const clockFromMinutes = (minutes: number) => `${String(Math.floor(minutes / 60) % 24).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;
const formatDuration = (appointment: Appointment) => appointment.patientId === null ? `${Number((appointment.durationMinutes / 60).toFixed(2)).toLocaleString("pt-BR")} ${appointment.durationMinutes === 60 ? "hora" : "horas"}` : `${appointment.durationMinutes} min`;
const appointmentsInSlot = (appointments: Appointment[], dateKey: string, slotStart: number) => appointments.filter((appointment) => {
  if (appointment.scheduledAt.slice(0, 10) !== dateKey) return false;
  const start = appointmentStartMinutes(appointment);
  if (!appointmentBlocksAgenda(appointment)) return Math.floor(start / 30) === Math.floor(slotStart / 30);
  return start < slotStart + 30 && start + appointment.durationMinutes > slotStart;
});

function CalendarAppointment({ appointment, patientName, slotStart, onOpen }: { appointment: Appointment; patientName: string; slotStart: number; onOpen: (appointment: Appointment) => void }) {
  const start = appointmentStartMinutes(appointment);
  const continuation = start < slotStart;
  return <button type="button" onClick={() => onOpen(appointment)} className={`calendar-event ${appointment.isBackup ? "calendar-backup" : appointmentTone(appointment.status)} ${continuation ? "calendar-continuation" : ""}`}><strong>{continuation ? patientName : `${appointment.scheduledAt.slice(11, 16)} · ${patientName}`}</strong><small>{continuation ? `Ocupado até ${clockFromMinutes(start + appointment.durationMinutes)}` : `${formatDuration(appointment)} · ${appointment.isBackup ? "Encaixe" : appointment.status}`}</small></button>;
}

function Agenda({ appointments, patients, confirmationMessage, name, onCreate, onCreateBlock, onEditMessage, onOpen, onStatus, onDelete }: { appointments: Appointment[]; patients: Patient[]; confirmationMessage: string; name: (id: number | null) => string; onCreate: (scheduledAt?: string) => void; onCreateBlock: (scheduledAt?: string) => void; onEditMessage: () => void; onOpen: (appointment: Appointment) => void; onStatus: (id: number, status: string) => void; onDelete: (appointment: Appointment) => void }) {
  const [mode, setMode] = useState<"calendar" | "month" | "list">("calendar");
  const [anchor, setAnchor] = useState(() => new Date());
  const start = weekStart(anchor);
  const week = Array.from({ length: 7 }, (_, index) => addCalendarDays(start, index));
  const slots = Array.from({ length: 28 }, (_, index) => 7 * 60 + index * 30);
  const monthStart = new Date(anchor.getFullYear(), anchor.getMonth(), 1);
  const monthGridStart = weekStart(monthStart);
  const monthDays = Array.from({ length: 42 }, (_, index) => addCalendarDays(monthGridStart, index));
  const ordered = [...appointments].sort((a, b) => a.scheduledAt.localeCompare(b.scheduledAt));
  const move = (direction: number) => setAnchor((current) => mode === "month" ? new Date(current.getFullYear(), current.getMonth() + direction, 1) : addCalendarDays(current, mode === "calendar" && window.matchMedia("(max-width: 767px)").matches ? direction : direction * 7));
  const monthPeriod = new Intl.DateTimeFormat("pt-BR", { month: "long", year: "numeric" }).format(anchor);
  const dayPeriod = new Intl.DateTimeFormat("pt-BR", { weekday: "long", day: "numeric", month: "long" }).format(anchor);
  const weekPeriod = `${dateBR(localDateKey(week[0]))} — ${dateBR(localDateKey(week[6]))}`;
  const openDay = (date: Date) => { setAnchor(date); setMode("calendar"); };

  return <div className="grid gap-6">
    <section className="agenda-hero overflow-hidden rounded-[26px] bg-gradient-to-br from-[#064c3a] via-[#08684e] to-[#0c7b5c] p-5 text-white shadow-xl shadow-emerald-950/10 sm:p-6">
      <div className="flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-4"><span className="grid size-12 place-items-center rounded-2xl bg-white/15 ring-1 ring-white/20"><CalendarDays className="text-[#ecd9a4]" /></span><div><p className="text-sm text-white/60">Agenda inteligente</p><h2 className="font-serif text-2xl font-semibold capitalize">{mode === "month" ? monthPeriod : mode === "list" ? "Todos os agendamentos" : <><span className="md:hidden">{dayPeriod}</span><span className="hidden md:inline">{weekPeriod}</span></>}</h2></div></div><div className="flex flex-wrap gap-2"><Button onClick={onEditMessage} variant="outline" className="border-white/25 bg-white/10 text-white hover:bg-white/20 hover:text-white"><MessageCircle /> Mensagem do WhatsApp</Button><Button onClick={() => onCreateBlock()} variant="outline" className="border-white/25 bg-white/10 text-white hover:bg-white/20 hover:text-white"><CalendarDays /> Bloquear horário</Button><Button onClick={() => onCreate()} className="bg-white text-[#07533f] hover:bg-[#f4fbf7]"><Plus /> Novo agendamento</Button></div></div>
      <div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-white/10 pt-5"><div className="flex items-center gap-2"><Button size="icon" variant="outline" className="border-white/20 bg-white/10 text-white hover:bg-white/20 hover:text-white" onClick={() => move(-1)}><ChevronLeft /></Button><Button variant="outline" className="border-white/20 bg-white/10 text-white hover:bg-white/20 hover:text-white" onClick={() => setAnchor(new Date())}>Hoje</Button><Button size="icon" variant="outline" className="border-white/20 bg-white/10 text-white hover:bg-white/20 hover:text-white" onClick={() => move(1)}><ChevronRight /></Button></div><div className="flex rounded-xl bg-black/10 p-1"><button onClick={() => setMode("calendar")} className={`rounded-lg px-3 py-2 text-sm font-medium md:hidden ${mode === "calendar" ? "bg-white text-[#07533f] shadow-sm" : "text-white/70"}`}>Dia</button><button onClick={() => setMode("calendar")} className={`hidden rounded-lg px-3 py-2 text-sm font-medium md:block ${mode === "calendar" ? "bg-white text-[#07533f] shadow-sm" : "text-white/70"}`}>Semana</button><button onClick={() => setMode("month")} className={`rounded-lg px-3 py-2 text-sm font-medium ${mode === "month" ? "bg-white text-[#07533f] shadow-sm" : "text-white/70"}`}>Mês</button><button onClick={() => setMode("list")} className={`rounded-lg px-3 py-2 text-sm font-medium ${mode === "list" ? "bg-white text-[#07533f] shadow-sm" : "text-white/70"}`}>Lista</button></div></div>
    </section>

    {mode === "calendar" && <section className="premium-card overflow-hidden rounded-[24px] border bg-white md:hidden"><div className="day-calendar"><div className="day-calendar-head"><span className="capitalize">{new Intl.DateTimeFormat("pt-BR", { weekday: "long" }).format(anchor)}</span><strong>{dateBR(localDateKey(anchor))}</strong><small>Toque em um horário livre para agendar</small></div>{slots.map((minutes) => { const hour = String(Math.floor(minutes / 60)).padStart(2, "0"); const minute = String(minutes % 60).padStart(2, "0"); const key = localDateKey(anchor); const items = appointmentsInSlot(ordered, key, minutes); const isFree = !items.some(appointmentBlocksAgenda); return <div key={minutes} className="day-row"><span className="day-time">{hour}:{minute}</span><div className="day-slot">{items.map((item) => <CalendarAppointment key={item.id} appointment={item} patientName={item.patientId === null ? item.title : name(item.patientId)} slotStart={minutes} onOpen={onOpen} />)}{isFree && <button type="button" className="day-free w-full" onClick={() => onCreate(`${key}T${hour}:${minute}`)}><Plus className="size-4" /> Horário livre</button>}</div></div>; })}</div></section>}

    {mode === "calendar" && <section className="premium-card hidden overflow-hidden rounded-[24px] border bg-white md:block"><div className="overflow-x-auto"><div className="weekly-calendar min-w-[980px]">
      <div className="calendar-corner">Horário</div>{week.map((date) => <div key={localDateKey(date)} className={`calendar-day-head ${localDateKey(date) === localDateKey(new Date()) ? "is-today" : ""}`}><span>{new Intl.DateTimeFormat("pt-BR", { weekday: "short" }).format(date)}</span><strong>{date.getDate()}</strong></div>)}
      {slots.flatMap((minutes) => { const hour = String(Math.floor(minutes / 60)).padStart(2, "0"); const minute = String(minutes % 60).padStart(2, "0"); return [<div key={`time-${minutes}`} className="calendar-time">{hour}:{minute}</div>, ...week.map((date) => { const key = localDateKey(date); const items = appointmentsInSlot(ordered, key, minutes); const isFree = !items.some(appointmentBlocksAgenda); const slotValue = `${key}T${hour}:${minute}`; return <div key={`${key}-${minutes}`} className="calendar-slot" aria-label={isFree ? `Agendar em ${dateBR(key)} às ${hour}:${minute}` : `Horário ocupado em ${dateBR(key)} às ${hour}:${minute}`}>{items.map((item) => <CalendarAppointment key={item.id} appointment={item} patientName={item.patientId === null ? item.title : name(item.patientId)} slotStart={minutes} onOpen={onOpen} />)}{isFree && <button type="button" className="slot-plus w-full" onClick={() => onCreate(slotValue)}><Plus className="size-3" /> livre</button>}</div>; })]; })}
    </div></div><div className="flex flex-wrap gap-4 border-t bg-[#fbfcfb] px-5 py-3 text-xs text-[#66756d]"><span><i className="inline-block size-2.5 rounded-full bg-[#4c9b78]" /> Agendado/confirmado</span><span><i className="inline-block size-2.5 rounded-full bg-[#8b65c2]" /> Encaixe/reserva</span><span><i className="inline-block size-2.5 rounded-full bg-[#d2a13d]" /> Compromisso pessoal</span><span><i className="inline-block size-2.5 rounded-full bg-[#5d7894]" /> Concluído</span><span><i className="inline-block size-2.5 rounded-full bg-[#c8786b]" /> Cancelado/faltou</span><span className="ml-auto">Toque em um compromisso para abrir as opções</span></div></section>}

    {mode === "month" && <section className="premium-card overflow-x-auto rounded-[24px] border bg-white"><div className="month-weekdays">{["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"].map((day) => <span key={day}>{day}</span>)}</div><div className="month-grid">{monthDays.map((date) => { const key = localDateKey(date); const items = ordered.filter((item) => item.scheduledAt.slice(0, 10) === key); const outside = date.getMonth() !== anchor.getMonth(); return <button type="button" key={key} onClick={() => openDay(date)} className={`month-day ${outside ? "outside" : ""} ${key === localDateKey(new Date()) ? "today" : ""}`}><span className="month-number">{date.getDate()}</span><span className="grid gap-1">{items.slice(0, 3).map((item) => <span key={item.id} className={`month-event ${item.isBackup ? "calendar-backup" : appointmentTone(item.status)}`}>{item.scheduledAt.slice(11, 16)} {item.patientId === null ? item.title : name(item.patientId)}{item.isBackup ? " · Encaixe" : ""}</span>)}{items.length > 3 && <small>+ {items.length - 3} compromisso(s)</small>}{!items.length && <small className="month-free">Horários livres</small>}</span></button>; })}</div></section>}

    {mode === "list" && <AgendaList appointments={ordered} patients={patients} confirmationMessage={confirmationMessage} name={name} onOpen={onOpen} onStatus={onStatus} onDelete={onDelete} />}
    {mode !== "list" && <AgendaList appointments={ordered.filter((item) => item.scheduledAt.slice(0, 10) >= localDateKey(new Date())).slice(0, 8)} patients={patients} confirmationMessage={confirmationMessage} name={name} onOpen={onOpen} onStatus={onStatus} onDelete={onDelete} compact />}
  </div>;
}

function AgendaList({ appointments, patients, confirmationMessage, name, onOpen, onStatus, onDelete, compact }: { appointments: Appointment[]; patients: Patient[]; confirmationMessage: string; name: (id: number | null) => string; onOpen: (appointment: Appointment) => void; onStatus: (id: number, status: string) => void; onDelete: (appointment: Appointment) => void; compact?: boolean }) {
  return <section className="premium-card rounded-[24px] border bg-white p-5 sm:p-6"><div><h2 className="text-xl font-semibold">{compact ? "Próximos compromissos" : "Todos os compromissos"}</h2><p className="text-sm text-[#7b8881]">Atendimentos e bloqueios pessoais em um só lugar</p></div><div className="mt-5 divide-y">{appointments.length ? appointments.map((appointment) => { const patient = patients.find((item) => item.id === appointment.patientId); const displayName = appointment.patientId === null ? appointment.title : name(appointment.patientId); const digits = patient?.phone.replace(/\D/g, "") || ""; const phone = digits.length === 10 || digits.length === 11 ? `55${digits}` : digits; const message = encodeURIComponent(formatConfirmationMessage(confirmationMessage, { name: patient?.name || "", date: dateBR(appointment.scheduledAt), time: appointment.scheduledAt.slice(11, 16), duration: formatDuration(appointment) })); return <div key={appointment.id} className="flex flex-wrap items-center gap-3 py-4"><div className="w-20 text-center"><strong className="text-lg text-[#08684e]">{appointment.scheduledAt.slice(11, 16)}</strong><p className="text-xs">{dateBR(appointment.scheduledAt)}</p></div><Avatar name={displayName} photo={patient?.profilePhoto} /><div className="min-w-[160px] flex-1"><strong>{displayName}</strong>{appointment.isBackup && <Badge className="ml-2 bg-[#eee7ff] text-[#6943a8]">Encaixe</Badge>}<p className="text-sm text-[#77847c]">{formatDuration(appointment)}{appointment.notes ? ` · ${appointment.notes}` : ""}</p></div>{appointment.patientId === null ? <Status value="Bloqueado" /> : <NativeSelect value={appointment.status} onChange={(event) => onStatus(appointment.id, event.target.value)} className="h-9 w-[138px] text-xs"><NativeSelectOption>Agendado</NativeSelectOption><NativeSelectOption>Confirmado</NativeSelectOption><NativeSelectOption>Concluído</NativeSelectOption><NativeSelectOption>Faltou</NativeSelectOption><NativeSelectOption>Cancelado</NativeSelectOption></NativeSelect>}{phone && <a href={`https://wa.me/${phone}?text=${message}`} target="_blank" rel="noreferrer" className="inline-flex h-9 items-center gap-2 rounded-lg bg-[#25d366] px-3 text-sm font-medium text-white transition hover:bg-[#1fb759]"><MessageCircle className="size-4" /> WhatsApp</a>}<Button variant="ghost" size="icon" onClick={() => onOpen(appointment)} title="Abrir opções"><Pencil className="size-4" /></Button><Button variant="ghost" size="icon" className="text-red-500" onClick={() => onDelete(appointment)} title="Excluir e liberar horário"><Trash2 className="size-4" /></Button></div>; }) : <EmptyState text="Nenhum compromisso agendado." />}</div></section>;
}

function ActionModal({ modal, setModal, data, remaining, submit, saving, editingPatient, editingSession, editingPackage, editingAppointment, preferredPatientId, preferredAppointmentAt }: { modal: Modal; setModal: (m: Modal) => void; data: ClinicData; remaining: (p: ClinicPackage) => number; submit: (e: FormEvent<HTMLFormElement>, action: string) => void; saving: boolean; editingPatient: Patient | null; editingSession: Session | null; editingPackage: ClinicPackage | null; editingAppointment: Appointment | null; preferredPatientId?: number; preferredAppointmentAt?: string }) {
  if (!modal) return null;
  const title = { patient: "Novo paciente", patientEdit: "Editar paciente", package: "Novo pacote", packageEdit: "Editar pacote", session: "Registrar sessão", sessionEdit: "Corrigir sessão", payment: "Registrar entrada", appointment: "Novo agendamento", appointmentEdit: "Alterar compromisso", block: "Bloquear horário pessoal", expense: "Nova despesa", whatsappMessage: "Mensagem de confirmação" }[modal];
  const action = { patient: "patient.create", patientEdit: "patient.update", package: "package.create", packageEdit: "package.update", session: "session.create", sessionEdit: "session.update", payment: "payment.create", appointment: "appointment.create", appointmentEdit: "appointment.update", block: "appointment.block", expense: "expense.create", whatsappMessage: "settings.confirmation-message.update" }[modal];
  return <Dialog open onOpenChange={(open) => !open && setModal(null)}><DialogContent mobileFullscreen className="mobile-dialog max-h-[90vh] overflow-y-auto rounded-[24px] border-[#dce8e1] sm:max-w-[600px]"><DialogHeader><DialogTitle className="font-serif text-2xl">{title}</DialogTitle><DialogDescription>Preencha os dados abaixo e salve.</DialogDescription></DialogHeader><form onSubmit={(event) => submit(event, action)} className="grid gap-4">
    {modal === "patientEdit" && editingPatient && <><input type="hidden" name="id" value={editingPatient.id} /><PhotoPicker name={editingPatient.name} defaultValue={editingPatient.profilePhoto} /><Field label="Nome completo" name="name" required defaultValue={editingPatient.name} /><DuplicatePatientHint /><Field label="Telefone" name="phone" defaultValue={editingPatient.phone} /><Field label="E-mail" name="email" type="email" defaultValue={editingPatient.email} /><TextField label="Observações" name="notes" defaultValue={editingPatient.notes} /></>}
    {modal === "patient" && <><PhotoPicker name="Novo paciente" /><Field label="Nome completo" name="name" required /><DuplicatePatientHint /><Field label="Telefone" name="phone" /><Field label="E-mail" name="email" type="email" /><TextField label="Observações" name="notes" /></>}
    {modal === "package" && <><PatientSelect patients={data.patients} defaultValue={preferredPatientId} /><Field label="Quantidade de sessões" name="totalSessions" type="number" min="1" defaultValue="5" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Data da contratação" name="purchasedAt" type="date" defaultValue={today} required /><Field label="Vencimento do pagamento" name="paymentDueDate" type="date" defaultValue={dueDateDefault} required /></div><Field label="Nome do pacote" name="name" /><Field label="Valor total (R$) — pode ser zero" name="totalAmount" type="number" step="0.01" min="0" defaultValue="0" /><Field label="Valor pago (R$)" name="paidAmount" type="number" step="0.01" min="0" defaultValue="0" /><Method name="paymentMethod" /><div className="rounded-xl bg-[#f4f7f5] p-3 text-xs leading-relaxed text-[#607068]">Use R$ 0,00 para atendimento gratuito, cortesia ou pacote antigo que não deve gerar cobrança no financeiro.</div></>}
    {modal === "packageEdit" && editingPackage && <><input type="hidden" name="id" value={editingPackage.id} /><div className="rounded-xl border border-[#d9e7df] bg-[#f4f9f6] p-4 text-sm"><span className="text-[#718078]">Paciente</span><strong className="mt-1 block">{data.patients.find((patient) => patient.id === editingPackage.patientId)?.name || "Paciente"}</strong><p className="mt-2 text-xs text-[#718078]">As sessões e os pagamentos já registrados serão preservados.</p></div><Field label="Nome do pacote" name="name" defaultValue={editingPackage.name} required /><Field label="Quantidade total de sessões" name="totalSessions" type="number" min={Math.max(1, data.sessions.filter((session) => session.packageId === editingPackage.id).length)} defaultValue={editingPackage.totalSessions} required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Data de início/contratação" name="purchasedAt" type="date" defaultValue={editingPackage.purchasedAt.slice(0, 10)} required /><Field label="Vencimento do pagamento" name="paymentDueDate" type="date" defaultValue={editingPackage.paymentDueDate?.slice(0, 10) || dueDateDefault} required /></div><Field label="Valor total (R$)" name="totalAmount" type="number" step="0.01" min={Number((editingPackage.paidAmountCents / 100).toFixed(2))} defaultValue={Number((editingPackage.totalAmountCents / 100).toFixed(2))} required /><Method name="paymentMethod" defaultValue={editingPackage.paymentMethod} /><div className="rounded-xl bg-[#fff9e9] p-3 text-xs leading-relaxed text-[#705c28]">O valor já pago, o histórico de pagamentos e as sessões realizadas não serão alterados por esta correção.</div></>}
    {modal === "session" && <SessionCreateFields data={data} remaining={remaining} preferredPatientId={preferredPatientId} />}
    {modal === "sessionEdit" && editingSession && <><input type="hidden" name="id" value={editingSession.id} /><div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">A correção será registrada no histórico de segurança.</div>{editingSession.packageId === null && <><div className="rounded-xl border border-[#cfe2d8] bg-[#f2f8f5] p-3 text-sm font-medium text-[#07533f]">Sessão avulsa</div><div className="grid gap-4 sm:grid-cols-2"><Field label="Valor da sessão (R$)" name="standaloneAmount" type="number" step="0.01" min="0" defaultValue={Number((editingSession.standaloneAmountCents / 100).toFixed(2))} required /><Field label="Valor já pago (R$)" name="standalonePaidAmount" type="number" step="0.01" min="0" defaultValue={Number((editingSession.standalonePaidCents / 100).toFixed(2))} required /></div><div className="grid gap-4 sm:grid-cols-2"><Method name="standalonePaymentMethod" defaultValue={editingSession.standalonePaymentMethod} /><Field label="Vencimento" name="standaloneDueDate" type="date" defaultValue={editingSession.standaloneDueDate?.slice(0, 10) || dueDateDefault} required /></div></>}<Field label="Data da sessão" name="performedAt" type="date" defaultValue={editingSession.performedAt.slice(0, 10)} required /><Field label="Procedimento realizado" name="procedureType" defaultValue={editingSession.procedureType} /><div className="grid gap-4 sm:grid-cols-2"><Field label="Medida de entrada" name="measurementIn" defaultValue={editingSession.measurementIn} /><Field label="Medida de saída" name="measurementOut" defaultValue={editingSession.measurementOut} /></div><TextField label="Evolução e observações" name="notes" defaultValue={editingSession.notes} /><TextField label="Intercorrências durante a sessão" name="occurrences" defaultValue={editingSession.occurrences} /></>}
    {modal === "payment" && <><PackageSelect packages={data.packages.filter((pkg) => pkg.totalAmountCents > 0 && pkg.paymentStatus !== "Pago")} data={data} remaining={remaining} preferredPatientId={preferredPatientId} /><Field label="Valor recebido (R$)" name="amount" type="number" step="0.01" min="0.01" required /><Field label="Data" name="paidAt" type="date" defaultValue={today} required /><Method name="method" /><TextField label="Observações" name="notes" /></>}
    {modal === "expense" && <><Field label="Descrição" name="description" placeholder="Ex.: Aluguel, materiais, internet" required /><ExpenseCategory /><Field label="Valor (R$)" name="amount" type="number" step="0.01" min="0.01" required /><Field label="Data do pagamento" name="paidAt" type="date" defaultValue={today} required /><TextField label="Observações" name="notes" /></>}
    {modal === "appointment" && <><SearchablePatientSelect patients={data.patients} defaultValue={preferredPatientId} /><AppointmentDateTimeField label="Data e horário do primeiro atendimento" defaultValue={preferredAppointmentAt} /><Field label="Duração em minutos" name="durationMinutes" type="number" min="10" step="5" defaultValue="50" /><AppointmentRecurrence /><AppointmentOverlapOption /><TextField label="Observações" name="notes" /></>}
    {modal === "block" && <><div className="rounded-xl border border-[#e8dbb6] bg-[#fff9e9] p-4 text-sm text-[#705c28]">Use este bloqueio para compromissos pessoais, reuniões, almoço ou qualquer período em que não poderá atender.</div><Field label="Nome do compromisso" name="title" placeholder="Ex.: Médico, unha, compromisso pessoal" required /><Field label="Data e horário inicial" name="scheduledAt" type="datetime-local" defaultValue={preferredAppointmentAt} required /><Field label="Duração em horas" name="durationHours" type="number" min="0.5" max="12" step="0.5" defaultValue="1" required /><AppointmentRecurrence /><TextField label="Observações" name="notes" /></>}
    {modal === "appointmentEdit" && editingAppointment && <><input type="hidden" name="id" value={editingAppointment.id} />{editingAppointment.patientId === null ? <Field label="Nome do compromisso" name="title" defaultValue={editingAppointment.title} required /> : <div className="rounded-xl bg-[#f2f8f5] p-4 text-sm"><span className="text-[#718078]">Paciente</span><strong className="mt-1 block">{data.patients.find((patient) => patient.id === editingAppointment.patientId)?.name || "Paciente"}</strong></div>}<AppointmentDateTimeField label="Data e horário" defaultValue={editingAppointment.scheduledAt.slice(0, 16)} />{editingAppointment.patientId === null ? <Field label="Duração em horas" name="durationHours" type="number" min="0.5" max="12" step="0.5" defaultValue={Number((editingAppointment.durationMinutes / 60).toFixed(2))} required /> : <Field label="Duração em minutos" name="durationMinutes" type="number" min="10" step="5" defaultValue={editingAppointment.durationMinutes} />}<TextField label="Observações" name="notes" defaultValue={editingAppointment.notes} /></>}
    {modal === "whatsappMessage" && <><div className="rounded-xl border border-[#cfe2d8] bg-[#f2f8f5] p-4 text-sm leading-relaxed text-[#52665c]">Escreva a mensagem do seu jeito. O sistema troca automaticamente os campos abaixo pelos dados do agendamento.</div><div className="grid gap-2"><Label htmlFor="confirmationMessage">Texto enviado pelo WhatsApp</Label><Textarea id="confirmationMessage" name="confirmationMessage" required maxLength={2000} defaultValue={data.settings.confirmationMessage} className="min-h-48 leading-relaxed" /></div><div className="rounded-xl bg-[#fff9e9] p-4 text-sm text-[#705c28]"><strong>Campos automáticos disponíveis:</strong><div className="mt-2 flex flex-wrap gap-2"><code className="rounded bg-white px-2 py-1">{"{nome}"}</code><code className="rounded bg-white px-2 py-1">{"{data}"}</code><code className="rounded bg-white px-2 py-1">{"{horario}"}</code><code className="rounded bg-white px-2 py-1">{"{duracao}"}</code></div><p className="mt-2 text-xs">Você pode mudar todas as palavras, mas mantenha esses campos onde deseja que os dados apareçam.</p></div></>}
    <div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setModal(null)}>Cancelar</Button><Button disabled={saving} className="bg-[#08684e]">{saving ? "Salvando..." : "Salvar"}</Button></div>
  </form></DialogContent></Dialog>;
}
function AppointmentActionsDialog({ appointment, patientName, saving, onClose, onEdit, onStatus, onDelete }: { appointment: Appointment | null; patientName: string; saving: boolean; onClose: () => void; onEdit: (appointment: Appointment) => void; onStatus: (appointment: Appointment, status: string) => void; onDelete: (appointment: Appointment) => void }) {
  const isBlock = appointment?.patientId === null;
  return <Dialog open={Boolean(appointment)} onOpenChange={(open) => !open && onClose()}><DialogContent className="rounded-[24px] sm:max-w-[480px]"><DialogHeader><DialogTitle className="font-serif text-2xl">{isBlock ? "Horário bloqueado" : "Opções do agendamento"}</DialogTitle><DialogDescription>Altere, atualize o status ou libere este horário.</DialogDescription></DialogHeader>{appointment && <><div className="rounded-2xl bg-[#f3f8f5] p-4"><div className="flex items-center gap-3"><Avatar name={patientName} /><div><strong>{patientName}</strong><p className="text-sm text-[#718078]">{dateBR(appointment.scheduledAt)} às {appointment.scheduledAt.slice(11, 16)} · {formatDuration(appointment)}</p></div></div>{appointment.notes && <p className="mt-3 border-t pt-3 text-sm text-[#65746c]">{appointment.notes}</p>}</div><div className="grid gap-2 sm:grid-cols-2"><Button variant="outline" onClick={() => onEdit(appointment)}><Pencil /> Alterar horário</Button>{!isBlock && <Button variant="outline" onClick={() => onStatus(appointment, "Confirmado")} disabled={saving}>Confirmar presença</Button>}{!isBlock && <Button variant="outline" className="text-amber-700" onClick={() => onStatus(appointment, "Faltou")} disabled={saving}>Marcar que faltou</Button>}{!isBlock && <Button variant="outline" className="text-red-600" onClick={() => onStatus(appointment, "Cancelado")} disabled={saving}>Cancelar e liberar</Button>}<Button className="bg-red-600 hover:bg-red-700 sm:col-span-2" onClick={() => onDelete(appointment)} disabled={saving}><Trash2 /> Excluir e liberar horário</Button></div></>}</DialogContent></Dialog>;
}
function WaitingListDialog({ open, data, saving, onClose, onAdd, onSchedule, onDelete }: { open: boolean; data: ClinicData; saving: boolean; onClose: () => void; onAdd: (payload: Record<string, unknown>) => Promise<void>; onSchedule: (patientId: number) => void; onDelete: (id: number) => void }) {
  return <Dialog open={open} onOpenChange={(next) => !next && onClose()}><DialogContent mobileFullscreen className="mobile-dialog max-h-[90vh] overflow-y-auto rounded-[24px] sm:max-w-[680px]"><DialogHeader><DialogTitle className="flex items-center gap-2 font-serif text-2xl"><Bell className="text-[#a26d20]" /> Lista de espera</DialogTitle><DialogDescription>Guarde aqui as pacientes que aguardam uma vaga e agende quando surgir um horário.</DialogDescription></DialogHeader>
    <form className="grid gap-4 rounded-2xl border border-[#d9e7df] bg-[#f5faf7] p-4" onSubmit={(event) => { event.preventDefault(); void onAdd(Object.fromEntries(new FormData(event.currentTarget).entries())); }}><SearchablePatientSelect patients={data.patients} /><Field label="Preferência de dias e horários" name="preference" placeholder="Ex.: segunda ou quarta, depois das 18h" /><TextField label="Observações" name="notes" /><Button disabled={saving} className="bg-[#08684e] hover:bg-[#07533f]"><Plus /> {saving ? "Salvando..." : "Adicionar à lista"}</Button></form>
    <div className="grid gap-3">{data.waitingList.length ? data.waitingList.map((entry) => { const patient = data.patients.find((item) => item.id === entry.patientId); if (!patient) return null; const phone = whatsappNumber(patient.phone); const message = encodeURIComponent(`Olá, ${patient.name}! Tudo bem? Surgiu uma possibilidade de horário para seu atendimento. Gostaria de verificar sua disponibilidade.`); return <article key={entry.id} className="rounded-2xl border bg-white p-4 shadow-sm"><div className="flex items-start gap-3"><Avatar name={patient.name} photo={patient.profilePhoto} /><div className="min-w-0 flex-1"><strong className="block truncate">{patient.name}</strong><p className="mt-1 text-sm text-[#607068]">{entry.preference || "Sem preferência de horário informada"}</p>{entry.notes && <p className="mt-2 text-xs text-[#7b8881]">{entry.notes}</p>}</div></div><div className="mt-4 flex flex-wrap gap-2">{phone && <a href={`https://wa.me/${phone}?text=${message}`} target="_blank" rel="noreferrer" className="inline-flex h-9 items-center gap-2 rounded-lg bg-[#25d366] px-3 text-sm font-medium text-white"><MessageCircle className="size-4" /> WhatsApp</a>}<Button type="button" size="sm" className="bg-[#08684e]" onClick={() => onSchedule(patient.id)}><CalendarDays /> Agendar</Button><Button type="button" size="sm" variant="outline" className="ml-auto text-red-600" onClick={() => onDelete(entry.id)} disabled={saving}><Trash2 /> Retirar</Button></div></article>; }) : <div className="rounded-2xl border border-dashed p-7 text-center text-sm text-[#718078]">Nenhuma paciente na lista de espera.</div>}</div>
  </DialogContent></Dialog>;
}
function DeleteDialog({ target, saving, onClose, onConfirm }: { target: DeleteTarget; saving: boolean; onClose: () => void; onConfirm: () => void }) { const session = target?.action === "session.delete"; return <Dialog open={Boolean(target)} onOpenChange={(open) => !open && onClose()}><DialogContent className="rounded-[24px] sm:max-w-[440px]"><DialogHeader><DialogTitle className="font-serif text-2xl">{session ? "Cancelar registro da sessão?" : "Remover registro?"}</DialogTitle><DialogDescription>{session ? <>A sessão será retirada da contagem, mas permanecerá preservada no histórico de segurança.</> : <>Você está removendo <strong>{target?.label}</strong>. Esta ação não poderá ser desfeita.</>}</DialogDescription></DialogHeader><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Voltar</Button><Button disabled={saving} className="bg-red-600 hover:bg-red-700" onClick={onConfirm}><Trash2 /> {saving ? "Salvando..." : session ? "Cancelar sessão" : "Remover"}</Button></div></DialogContent></Dialog>; }
function EmptyState({ text }: { text: string }) { return <div className="grid place-items-center gap-2 py-14 text-center text-[#7d8a83]"><span className="grid size-12 place-items-center rounded-full bg-[#edf5f0]"><Sparkles className="size-5 text-[#398069]" /></span><p>{text}</p></div>; }
function Field({ label, name, ...props }: { label: string; name: string } & React.ComponentProps<typeof Input>) { return <div className="grid gap-2"><Label htmlFor={name}>{label}</Label><Input id={name} name={name} className="h-11" {...props} /></div>; }
function AppointmentDateTimeField({ label, defaultValue = "" }: { label: string; defaultValue?: string }) { const [value, setValue] = useState(defaultValue); const selected = value ? new Intl.DateTimeFormat("pt-BR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" }).format(new Date(`${value.slice(0, 10)}T12:00:00`)) : ""; return <div className="grid gap-2"><Label htmlFor="scheduledAt">{label}</Label><Input id="scheduledAt" name="scheduledAt" type="datetime-local" value={value} onChange={(event) => setValue(event.target.value)} className="h-12" required />{selected && <div className="rounded-xl border border-[#cfe2d8] bg-[#eef7f2] px-4 py-3 text-sm font-semibold capitalize text-[#07533f]"><CalendarDays className="mr-2 inline size-4" />{selected}{value.slice(11, 16) ? ` às ${value.slice(11, 16)}` : ""}</div>}<p className="text-xs text-[#6e7f76]">Depois de escolher, o dia da semana aparecerá destacado acima.</p></div>; }
function DuplicatePatientHint() { return <p className="-mt-2 rounded-lg bg-[#fff9e9] px-3 py-2 text-xs leading-relaxed text-[#705c28]">Para evitar prontuários duplicados, não é possível salvar duas pacientes com o mesmo nome completo.</p>; }
function TextField({ label, name, defaultValue }: { label: string; name: string; defaultValue?: string }) { return <div className="grid gap-2"><Label htmlFor={name}>{label}</Label><Textarea id={name} name={name} defaultValue={defaultValue} /></div>; }
function PhotoPicker({ name, defaultValue = "" }: { name: string; defaultValue?: string }) {
  const [photo, setPhoto] = useState(defaultValue); const [processing, setProcessing] = useState(false);
  const choosePhoto = async (file?: File) => { if (!file) return; if (!file.type.startsWith("image/")) { toast.error("Escolha uma imagem válida."); return; } if (file.size > 10_000_000) { toast.error("Escolha uma foto com até 10 MB."); return; } setProcessing(true); try { const source = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); }); const image = await new Promise<HTMLImageElement>((resolve, reject) => { const value = new Image(); value.onload = () => resolve(value); value.onerror = reject; value.src = source; }); const size = 512; const scale = Math.min(1, size / Math.max(image.width, image.height)); const canvas = document.createElement("canvas"); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); canvas.getContext("2d")?.drawImage(image, 0, 0, canvas.width, canvas.height); setPhoto(canvas.toDataURL("image/jpeg", .82)); } catch { toast.error("Não foi possível preparar essa foto."); } finally { setProcessing(false); } };
  return <div className="rounded-2xl border bg-[#f7faf8] p-4"><input type="hidden" name="profilePhoto" value={photo} /><div className="flex items-center gap-4"><Avatar name={name} photo={photo} large /><div className="flex-1"><Label htmlFor="patient-photo">Foto do paciente</Label><p className="mt-1 text-xs text-[#7a8880]">A imagem será otimizada automaticamente.</p><div className="mt-3 flex flex-wrap gap-2"><label htmlFor="patient-photo" className="inline-flex h-9 cursor-pointer items-center rounded-lg bg-[#08684e] px-3 text-sm font-medium text-white hover:bg-[#07533f]">{processing ? "Preparando..." : photo ? "Trocar foto" : "Escolher foto"}</label>{photo && <Button type="button" size="sm" variant="ghost" className="text-red-500" onClick={() => setPhoto("")}>Remover</Button>}</div><input id="patient-photo" type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" disabled={processing} onChange={(event) => choosePhoto(event.target.files?.[0])} /></div></div></div>;
}
function PatientSelect({ patients, defaultValue }: { patients: Patient[]; defaultValue?: number }) { return <div className="grid gap-2"><Label>Paciente</Label><NativeSelect name="patientId" required className="h-11 w-full" defaultValue={defaultValue || ""}><NativeSelectOption value="">Selecione</NativeSelectOption>{patients.map((patient) => <NativeSelectOption key={patient.id} value={patient.id}>{patient.name}</NativeSelectOption>)}</NativeSelect></div>; }
function SessionCreateFields({ data, remaining, preferredPatientId }: { data: ClinicData; remaining: (p: ClinicPackage) => number; preferredPatientId?: number }) {
  const availablePackages = data.packages.filter((pkg) => remaining(pkg) > 0 && (!preferredPatientId || pkg.patientId === preferredPatientId));
  const [kind, setKind] = useState<"package" | "standalone">(availablePackages.length ? "package" : "standalone");
  return <>
    <div className="grid gap-2"><Label>Tipo da sessão</Label><NativeSelect name="sessionKind" value={kind} onChange={(event) => setKind(event.target.value as "package" | "standalone")} className="h-11 w-full"><NativeSelectOption value="package">Usar uma sessão de um pacote</NativeSelectOption><NativeSelectOption value="standalone">Sessão avulsa, sem pacote</NativeSelectOption></NativeSelect></div>
    {kind === "package" ? <PackageSelect packages={data.packages.filter((pkg) => remaining(pkg) > 0)} data={data} remaining={remaining} preferredPatientId={preferredPatientId} /> : <><PatientSelect patients={data.patients} defaultValue={preferredPatientId} /><div className="rounded-xl border border-[#cfe2d8] bg-[#f2f8f5] p-3 text-sm text-[#52665c]">A sessão será registrada diretamente no prontuário e não diminuirá nenhuma sessão de pacote.</div><div className="grid gap-4 sm:grid-cols-2"><Field label="Valor da sessão (R$) — pode ser zero" name="standaloneAmount" type="number" step="0.01" min="0" defaultValue="0" /><Field label="Valor pago agora (R$)" name="standalonePaidAmount" type="number" step="0.01" min="0" defaultValue="0" /></div><div className="grid gap-4 sm:grid-cols-2"><Method name="standalonePaymentMethod" /><Field label="Vencimento do pagamento" name="standaloneDueDate" type="date" defaultValue={dueDateDefault} /></div><div className="rounded-xl bg-[#f4f7f5] p-3 text-xs leading-relaxed text-[#607068]">Com R$ 0,00, a sessão ficará como “Sem cobrança” e não será somada ao financeiro.</div></>}
    <Field label="Data da sessão" name="performedAt" type="date" defaultValue={today} required /><Field label="Procedimento realizado" name="procedureType" placeholder="Ex.: Massagem modeladora, fisioterapia" /><div className="grid gap-4 sm:grid-cols-2"><Field label="Medida de entrada" name="measurementIn" placeholder="Ex.: 92 cm" /><Field label="Medida de saída" name="measurementOut" placeholder="Ex.: 89 cm" /></div><TextField label="Evolução e observações" name="notes" /><TextField label="Intercorrências durante a sessão" name="occurrences" />
  </>;
}
function SearchablePatientSelect({ patients, defaultValue }: { patients: Patient[]; defaultValue?: number }) {
  const initial = patients.find((patient) => patient.id === defaultValue);
  const [query, setQuery] = useState(initial?.name || "");
  const [selectedId, setSelectedId] = useState<number | undefined>(initial?.id);
  const [open, setOpen] = useState(false);
  const normalized = query.trim().toLocaleLowerCase("pt-BR");
  const filtered = patients.filter((patient) => `${patient.name} ${patient.phone} ${patient.email}`.toLocaleLowerCase("pt-BR").includes(normalized)).slice(0, 8);
  const choose = (patient: Patient) => { setSelectedId(patient.id); setQuery(patient.name); setOpen(false); };
  return <div className="grid gap-2"><Label htmlFor="appointment-patient-search">Paciente</Label><input type="hidden" name="patientId" value={selectedId || ""} /><div className="relative"><Search className="pointer-events-none absolute left-3 top-3.5 size-4 text-[#6f8178]" /><Input id="appointment-patient-search" value={query} autoComplete="off" placeholder="Digite o nome, telefone ou e-mail..." className="h-12 pl-10 pr-10" aria-expanded={open} aria-controls="appointment-patient-results" onFocus={() => setOpen(true)} onChange={(event) => { setQuery(event.target.value); setSelectedId(undefined); setOpen(true); }} onKeyDown={(event) => { if (event.key === "Enter" && open && filtered[0]) { event.preventDefault(); choose(filtered[0]); } if (event.key === "Escape") setOpen(false); }} />{selectedId && <span className="pointer-events-none absolute right-3 top-3 grid size-6 place-items-center rounded-full bg-[#dff2e8] text-xs font-bold text-[#087052]">✓</span>}</div>{open && <div id="appointment-patient-results" role="listbox" className="max-h-56 overflow-y-auto rounded-xl border border-[#d7e4dd] bg-white p-1.5 shadow-lg">{filtered.length ? filtered.map((patient) => <button key={patient.id} type="button" role="option" aria-selected={patient.id === selectedId} onClick={() => choose(patient)} className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left transition hover:bg-[#edf7f1] focus:bg-[#edf7f1] focus:outline-none"><Avatar name={patient.name} photo={patient.profilePhoto} /><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{patient.name}</strong><small className="block truncate text-[#748179]">{patient.phone || patient.email || "Paciente cadastrado"}</small></span></button>) : <p className="px-3 py-5 text-center text-sm text-[#748179]">Nenhum paciente encontrado.</p>}</div>}<p className="text-xs text-[#6e7f76]">{selectedId ? "Paciente selecionado. Digite novamente para trocar." : "Digite e toque no paciente correto antes de salvar."}</p></div>;
}
function PackageSelect({ packages, data, remaining, preferredPatientId }: { packages: ClinicPackage[]; data: ClinicData; remaining: (p: ClinicPackage) => number; preferredPatientId?: number }) { const visible = preferredPatientId ? packages.filter((pkg) => pkg.patientId === preferredPatientId) : packages; return <div className="grid gap-2"><Label>Pacote</Label><NativeSelect name="packageId" required className="h-11 w-full" defaultValue={visible[0]?.id || ""}><NativeSelectOption value="">Selecione</NativeSelectOption>{visible.map((pkg) => <NativeSelectOption key={pkg.id} value={pkg.id}>{data.patients.find((patient) => patient.id === pkg.patientId)?.name} · {pkg.name} · {remaining(pkg)} restantes</NativeSelectOption>)}</NativeSelect></div>; }
function Method({ name, defaultValue }: { name: string; defaultValue?: string }) { return <div className="grid gap-2"><Label>Forma de pagamento</Label><NativeSelect name={name} className="h-11 w-full" defaultValue={defaultValue}><NativeSelectOption>Pix</NativeSelectOption><NativeSelectOption>Dinheiro</NativeSelectOption><NativeSelectOption>Cartão</NativeSelectOption><NativeSelectOption>Transferência</NativeSelectOption><NativeSelectOption>Não informado</NativeSelectOption></NativeSelect></div>; }
function AppointmentRecurrence() { return <div className="grid gap-2 rounded-xl border border-[#d9e7df] bg-[#f4f9f6] p-4"><Label htmlFor="repeatWeeks">Repetição do horário</Label><NativeSelect id="repeatWeeks" name="repeatWeeks" className="h-11 w-full" defaultValue="1"><NativeSelectOption value="1">Somente este atendimento</NativeSelectOption><NativeSelectOption value="2">Toda semana por 2 semanas</NativeSelectOption><NativeSelectOption value="4">Toda semana por 4 semanas</NativeSelectOption><NativeSelectOption value="8">Toda semana por 8 semanas</NativeSelectOption><NativeSelectOption value="12">Toda semana por 12 semanas</NativeSelectOption><NativeSelectOption value="24">Toda semana por 6 meses</NativeSelectOption><NativeSelectOption value="52">Toda semana por 1 ano</NativeSelectOption></NativeSelect><p className="text-xs leading-relaxed text-[#6e7f76]">O sistema mantém o mesmo dia e horário e verifica todas as semanas antes de salvar.</p></div>; }
function AppointmentOverlapOption() { return <label className="flex cursor-pointer items-start gap-3 rounded-xl border border-[#ddd2f3] bg-[#f8f5ff] p-4"><input type="checkbox" name="allowOverlap" className="mt-1 size-4 accent-[#7048ad]" /><span><strong className="block text-sm text-[#56368a]">Agendar como encaixe ou reserva</strong><small className="mt-1 block leading-relaxed text-[#74658b]">Use somente quando quiser colocar um segundo paciente no mesmo período. O sistema permite no máximo dois e continua protegendo compromissos pessoais.</small></span></label>; }
function ExpenseCategory() { return <div className="grid gap-2"><Label>Categoria</Label><NativeSelect name="category" className="h-11 w-full"><NativeSelectOption>Materiais</NativeSelectOption><NativeSelectOption>Aluguel</NativeSelectOption><NativeSelectOption>Serviços</NativeSelectOption><NativeSelectOption>Equipamentos</NativeSelectOption><NativeSelectOption>Marketing</NativeSelectOption><NativeSelectOption>Impostos</NativeSelectOption><NativeSelectOption>Outros</NativeSelectOption></NativeSelect></div>; }
function Avatar({ name, photo, large }: { name: string; photo?: string; large?: boolean }) { const image = photo || (name === "Maria Carolini" ? "/dra-maria-carolini.jpg" : ""); return <span role={image ? "img" : undefined} aria-label={image ? `Foto de ${name}` : undefined} style={image ? { backgroundImage: `url(${image})`, backgroundSize: "cover", backgroundPosition: "center 32%" } : undefined} className={`avatar-3d grid shrink-0 place-items-center rounded-full bg-[#dcebe4] font-semibold text-[#07533f] ${large ? "size-14" : "size-10 text-sm"}`}>{!image && initials(name)}</span>; }
function Status({ value }: { value: string }) { const good = ["Pago", "Em andamento", "Agendado", "Confirmado", "Concluído"].includes(value); return <Badge className={good ? "bg-[#dcf2e6] text-[#087052]" : ["Parcial", "Bloqueado"].includes(value) ? "bg-[#fff0d7] text-[#93611a]" : "bg-[#fde4e2] text-[#a74238]"}>{value}</Badge>; }
